QB("geo", [
["1.1","Define",2,"Define natural increase.","The birth rate minus the death rate|birth rate|minus|death rate","Given per 1000 people or as a percentage, and excluding migration|per 1000|percentage|excluding migration|without migration",{model:"Natural increase is the birth rate minus the death rate, usually given per 1000 people per year or as a percentage, and excluding migration.",tip:"Include 'excluding migration' to show precision."}],
["1.1","Outline",2,"Outline the shape of a population pyramid for a low-income country.","A wide base, showing a high birth rate and many young people|wide base|broad base|high birth rate|many young","Narrowing quickly with age, showing a high death rate and low life expectancy|narrow|narrows|tapers|high death rate|low life expectancy",{model:"The pyramid has a wide base, from a high birth rate and many children, and narrows quickly towards the top because of a high death rate and low life expectancy.",tip:"Describe the shape and explain each part."}],
["1.2","Outline",2,"Outline two pull factors that attract migrants.","Jobs and higher wages|jobs|work|employment|wages","Better services such as education and healthcare|education|schools|healthcare|hospitals|services","Safety, freedom or family links|safety|freedom|family|security",{model:"Migrants are attracted by jobs and higher wages, and by better services such as schools and hospitals.",tip:"Two different types of factor (economic, social)."}],
["1.2","Define",2,"Define an internally displaced person (IDP).","Someone forced to flee their home|forced|flee|fled|forced from their home","But who stays within their own country's borders|own country|within|borders|not crossed",{model:"An internally displaced person has been forced to flee their home, for example by conflict or disaster, but remains within their own country.",tip:"The difference from a refugee is not crossing a border."}],
["1.3","Outline",2,"Outline one advantage and one disadvantage of an anti-natalist policy such as China's one-child policy.","Advantage: it slowed population growth and eased pressure on resources|slowed|slows|reduced growth|resources|pressure","Disadvantage: an ageing population, a gender imbalance or human rights abuses|ageing|aging|gender imbalance|sex ratio|human rights|forced",{model:"The one-child policy slowed population growth, easing pressure on resources, but it created a rapidly ageing population and a gender imbalance.",tip:"Label the advantage and the disadvantage."}],
["1.3","Outline",2,"Outline how gender equality can affect fertility rates.","Educated women with careers tend to marry later and have fewer children|education|educated|careers|later|fewer children","They have more access to contraception and family planning|contraception|family planning|choice",{model:"When women are educated and have careers, they tend to marry later and have fewer children, and they have more access to contraception and family planning.",tip:"Education is the most important link."}],
["2.1","Outline",2,"Outline how the natural greenhouse effect keeps the Earth warm.","Short-wave radiation from the Sun passes through the atmosphere and heats the surface|short wave|shortwave|sunlight|passes through","The surface gives off long-wave (infrared) radiation, some of which greenhouse gases absorb and re-emit|long wave|longwave|infrared|absorb|re emit|trap",{model:"Short-wave radiation from the Sun passes through the atmosphere and warms the surface. The surface emits long-wave infrared radiation, and greenhouse gases absorb and re-emit some of it, warming the lower atmosphere.",tip:"Short-wave in, long-wave out, partly trapped."}],
["2.1","Explain",2,"Explain how deforestation contributes to climate change.","Fewer trees absorb less carbon dioxide through photosynthesis|absorb|photosynthesis|carbon sink|sink","Burning or decaying trees release their stored carbon as carbon dioxide|release|burning|burned|stored carbon|decay",{model:"Forests are carbon sinks: fewer trees means less CO₂ absorbed by photosynthesis, and burning or rotting trees releases their stored carbon as CO₂.",tip:"Two effects: less absorbed, more released."}],
["2.2","Outline",2,"Outline how sea-level rise affects coastal communities.","More flooding and coastal erosion|flooding|floods|erosion","Homes and farmland are lost and salt water contaminates supplies, forcing people to move|salt|salinisation|migration|displaced|farmland|homes",{model:"Rising seas increase flooding and coastal erosion, destroying homes and farmland, and salt water contaminates water supplies, forcing some communities to move.",tip:"Physical effect, then human effect."}],
["2.2","Outline",2,"Outline one effect of climate change on agriculture.","Changing rainfall and more droughts or floods reduce crop yields|drought|droughts|yields|rainfall|crop failure","Crops' growing areas shift and pests and diseases spread|shift|pests|diseases|growing season|longer",{model:"More frequent droughts and changing rainfall reduce crop yields in many regions, and warmer temperatures let pests and diseases spread to new areas.",tip:"Say how the change affects farming."}],
["2.3","Outline",2,"Outline how carbon trading works.","A cap limits total emissions and permits are issued|cap|permits|allowances|limit","Firms that emit less can sell their spare permits to firms that emit more|sell|buy|spare",{model:"A government sets a cap on total emissions and issues permits. Firms that cut emissions can sell their spare permits to firms that emit more, so emissions are cut where it is cheapest.",tip:"Cap first, then trade."}],
["2.3","Outline",2,"Outline one way a city can adapt to climate change.","For example flood defences, green roofs, more trees or better water storage|flood defences|green roofs|shade|cooling|water storage|sea walls|trees","Reducing harm from heatwaves, floods or droughts|heatwaves|heat|floods|harm|vulnerability",{model:"A city can plant trees and build green roofs to provide shade and cool the air, reducing the harm of heatwaves.",tip:"Adaptation reduces the impact; it doesn't cut emissions."}],
["3.1","Outline",2,"Outline why the growth of the global middle class increases resource consumption.","Rising incomes mean more spending on meat, cars and consumer goods|meat|cars|goods|consumer|spending","Which increases demand for energy, water and land|energy|water|land|demand",{model:"As incomes rise, people buy more meat, cars and consumer goods, which increases demand for energy, water and land.",tip:"Link income to specific types of consumption."}],
["3.1","Define",2,"Define the Human Development Index (HDI).","A composite measure of human development|composite|measure|combined","Combining life expectancy, education and income per head|life expectancy|education|schooling|income|gni",{model:"The HDI is a composite measure of development that combines life expectancy, education (years of schooling) and income (GNI per capita).",tip:"Name all three components."}],
["3.2","Outline",2,"Outline the energy security risks of relying on imported fossil fuels.","Supplies can be cut off, or prices can rise, because of conflict or politics|cut off|prices|conflict|political|disruption","Which harms the economy and households|economy|households|costs|shortages",{model:"An importing country depends on other states, so conflict or politics can cut off supplies or push up prices, harming its economy and households.",tip:"Explain the dependence, then the consequence."}],
["3.2","Outline",2,"Outline one advantage and one disadvantage of nuclear power.","Advantage: low carbon emissions and a reliable output|low carbon|reliable|no emissions|baseload","Disadvantage: radioactive waste, the risk of accidents, or high cost|radioactive|waste|accident|chernobyl|fukushima|expensive|cost",{model:"Nuclear power produces very little carbon dioxide and gives a reliable supply, but it creates radioactive waste and carries a risk of accidents such as Fukushima.",tip:"One clear advantage and one clear disadvantage."}],
["3.3","Outline",2,"Outline the purpose of the UN Sustainable Development Goals (SDGs).","17 global targets agreed in 2015, to be met by 2030|17|2015|2030|targets","To end poverty, protect the planet and improve well-being|poverty|planet|environment|well being|inequality",{model:"The SDGs are 17 global targets agreed by the UN in 2015 for 2030, aiming to end poverty, protect the planet and improve well-being for all.",tip:"When they were agreed, and what they aim to do."}],
["3.3","Outline",2,"Outline how recycling contributes to resource stewardship.","Materials are reused instead of extracting new raw materials|raw materials|reuse|reused|extract","Reducing waste, landfill and energy use|landfill|waste|energy",{model:"Recycling reuses materials instead of extracting new raw materials, which conserves resources and reduces waste, landfill and energy use.",tip:"Conserving resources is the stewardship link."}],
["4.1","Outline",2,"Outline one way a country can increase its hard power.","Building military strength, such as a larger army, navy or nuclear weapons|military|army|navy|weapons|nuclear","Or using economic strength to pressure others, such as sanctions|economic|sanctions|coerce|trade",{model:"A country can increase its hard power by building military strength, such as a larger navy, or by using its economic weight to impose sanctions.",tip:"Hard power is coercion; soft power is attraction."}],
["4.1","Outline",2,"Outline the role of the G20 in global governance.","It brings together the world's major economies|major economies|largest economies|20 countries","To coordinate economic policy and respond to global crises|coordinate|policy|crisis|financial crisis|cooperation",{model:"The G20 brings together the world's largest economies to coordinate economic policy and respond to global crises, as it did in the 2008 financial crisis.",tip:"Who is in it and what it does."}],
["4.2","Outline",2,"Outline one reason why global trade has grown.","Cheaper, faster transport such as container shipping|container|containerisation|shipping|transport","Trade agreements have reduced tariffs (WTO)|tariffs|trade agreements|wto|free trade",{model:"Container shipping has made transport much cheaper and faster, and trade agreements through the WTO have reduced tariffs.",tip:"Name the factor and say how it helps trade."}],
["4.2","Define",2,"Define a global supply chain.","The network of firms and places involved in making and delivering a product|network|firms|making|production|delivering","With parts and processes spread across several countries|countries|across|several",{model:"A global supply chain is the network of firms and places involved in making and delivering a product, with its parts and processes spread across several countries.",tip:"Mention the international spread."}],
["4.3","Outline",2,"Outline how the internet has changed global interactions.","It allows instant, cheap communication across the world|instant|communication|cheap|fast","Enabling e-commerce, remote work and the spread of ideas and culture|e commerce|online|remote|ideas|culture|social media",{model:"The internet allows instant, cheap communication worldwide, enabling online shopping, remote work and the rapid spread of ideas and culture.",tip:"Give specific types of interaction."}],
["4.3","Outline",2,"Outline one physical factor that limits global interactions.","For example mountains, deserts, a landlocked location or an extreme climate|mountains|deserts|landlocked|climate|isolation|distance","Which makes transport and communication harder and more expensive|transport|costly|expensive|harder|difficult",{model:"Being landlocked, like Bolivia, makes trade harder and more expensive because goods must cross other countries to reach ports.",tip:"Name the factor and its effect."}],
["5.1","Outline",2,"Outline one way aid can help development.","Funding health care, schools or infrastructure|health|schools|infrastructure|education|vaccines","Which improves living standards and future growth|living standards|growth|poverty|quality of life",{model:"Aid can fund vaccination programmes and schools, improving health and education, which raises living standards and future growth.",tip:"What the aid pays for and how that helps."}],
["5.1","Outline",2,"Outline one criticism of international aid.","It can create dependency or be lost to corruption|dependency|corruption|tied aid|tied","Or it may not reach the poorest people|poorest|not reach|inappropriate|donor interests",{model:"Aid can create dependency or be lost to corruption, so it may not reach the poorest people.",tip:"Explain why the criticism matters."}],
["5.2","Outline",2,"Outline how globalization can threaten cultural diversity.","Global brands and media spread one dominant, often Western, culture|western|americanisation|americanization|global brands|media|dominant","So local languages, traditions or businesses decline|languages|traditions|decline|lost|homogenisation|homogenization",{model:"Global brands and Western media spread a dominant culture, so local languages, traditions and businesses can decline: a process called cultural homogenization.",tip:"Use the term homogenization."}],
["5.2","Define",2,"Define a diaspora.","A population that has spread from its original homeland|homeland|spread|scattered|dispersed","Living in other countries while keeping cultural ties to it|other countries|abroad|cultural ties|identity",{model:"A diaspora is a population that has spread from its original homeland to live in other countries, while keeping cultural ties to it, such as the Indian diaspora.",tip:"An example helps."}],
["5.3","Outline",2,"Outline one reason for anti-globalization protests.","Concern about inequality, job losses or the exploitation of workers|inequality|job losses|exploitation|sweatshops|workers","Or about environmental damage and the power of TNCs|environment|environmental|tncs|corporations|power",{model:"Protesters argue that globalization increases inequality and exploits workers in sweatshops, while large TNCs gain too much power.",tip:"Say what is being protested and why."}],
["5.3","Outline",2,"Outline how fair trade helps producers.","Producers are paid a guaranteed minimum price|minimum price|guaranteed|fair price","Plus a premium for community projects, with better working conditions|premium|community|working conditions",{model:"Fair trade guarantees producers a minimum price for their goods, plus a premium for community projects such as schools, and requires better working conditions.",tip:"Price and premium are the two key features."}],
["6.1","Outline",2,"Outline how sanctions can affect global interactions.","They restrict trade, investment or finance with a country|restrict|ban|trade|investment|finance","Raising prices and breaking supply chains for other countries too|prices|supply chains|shortages",{model:"Sanctions restrict trade and finance with a country, which can raise prices and break supply chains for other countries too, as with energy after sanctions on Russia.",tip:"Show the knock-on effect beyond the target country."}],
["6.1","Outline",2,"Outline why cyberattacks are a growing global risk.","Economies depend on digital networks and data|digital|networks|internet|data|dependent","Attacks can shut down infrastructure, steal data or cost billions|infrastructure|steal|ransomware|cost|shut down",{model:"Economies now depend on digital networks, so cyberattacks can shut down infrastructure such as hospitals or pipelines, steal data, and cost billions.",tip:"Dependence plus the possible damage."}],
["6.2","Outline",2,"Outline how plastic pollution in the oceans crosses borders.","Ocean currents carry plastic far from where it entered the sea|currents|carried|gyre|gyres","So it harms other countries' coasts and wildlife, needing international cooperation|other countries|international|cooperation|coasts|wildlife",{model:"Ocean currents carry plastic thousands of kilometres into gyres and onto other countries' coasts, harming wildlife far from its source, so international cooperation is needed.",tip:"Explain the movement and why it's a shared problem."}],
["6.2","Outline",2,"Outline how pandemics spread through global networks.","Air travel moves infected people quickly between countries|air travel|flights|travel|passengers","So a disease can reach many countries within days, as COVID-19 did|days|quickly|covid|many countries",{model:"Air travel moves infected people between countries within hours, so a disease such as COVID-19 can reach many countries in days.",tip:"Name the network (air travel) and an example."}],
["6.3","Outline",2,"Outline one strategy that increases a country's resilience to global risks.","Diversifying trade partners, or stockpiling food, medicines or energy|diversify|diversifying|stockpile|stockpiling|reserves","So shocks elsewhere cause less harm|shocks|less harm|recover|withstand",{model:"A country can diversify its suppliers and keep stockpiles of food, medicine and energy, so a shock elsewhere causes less harm.",tip:"Strategy plus how it reduces harm."}],
["6.3","Define",2,"Define reshoring.","Bringing production back to the home country|back|home country|return|domestic","From overseas locations|overseas|abroad|offshore",{model:"Reshoring is bringing production back to the home country from overseas locations.",tip:"It is the opposite of offshoring."}],
["A.1","Define",2,"Define a drainage basin.","The area of land drained by a river and its tributaries|area of land|drained|tributaries","Separated from other basins by a watershed|watershed",{model:"A drainage basin is the area of land drained by a river and its tributaries, separated from neighbouring basins by a watershed.",tip:"Include the watershed."}],
["A.1","Outline",2,"Outline how a meander forms.","The water flows fastest on the outside of a bend, eroding it into a river cliff|fastest|outside|erosion|eroding|river cliff","It flows slowest on the inside, depositing sediment as a slip-off slope|slowest|inside|deposition|depositing|slip off",{model:"On the outside of a bend the water flows fastest and erodes a river cliff. On the inside it flows slowest and deposits sediment, forming a slip-off slope, so the bend grows.",tip:"Erosion on the outside, deposition on the inside."}],
["A.2","Outline",2,"Outline two human factors that increase flood risk.","Urbanization: impermeable surfaces increase run-off|urbanisation|urbanization|impermeable|concrete|tarmac|run off|runoff","Deforestation reduces interception, so more water runs off|deforestation|interception|trees","Building on floodplains|floodplain|floodplains",{model:"Urbanization replaces soil with impermeable concrete, so more rain runs off quickly, and deforestation reduces interception, adding to run-off.",tip:"Explain how each factor speeds water to the river."}],
["A.2","Outline",2,"Outline how a storm hydrograph can show flood risk.","A short lag time and steep rising limb mean water reaches the river quickly|short lag|steep|rising limb|quickly","A high peak discharge above bankfull capacity means flooding|peak discharge|high peak|bankfull|discharge",{model:"A short lag time and steep rising limb show water reaching the river quickly, and if the peak discharge exceeds bankfull capacity, the river floods.",tip:"Use the hydrograph vocabulary: lag time, rising limb, peak discharge."}],
["A.3","Outline",2,"Outline one cause of falling groundwater levels.","Over-abstraction for irrigation, industry or cities|abstraction|pumping|irrigation|wells|over use","Faster than the aquifer is recharged by rainfall|recharge|recharged|replenished|faster",{model:"Groundwater is pumped out for irrigation and cities faster than rainfall can recharge the aquifer, so the water table falls.",tip:"The imbalance between use and recharge is the key."}],
["A.3","Outline",2,"Outline why agriculture can reduce water quality.","Fertiliser run-off adds nitrates and phosphates, causing eutrophication|fertiliser|fertilizer|nitrates|phosphates|eutrophication","Pesticides and animal waste pollute rivers and groundwater|pesticides|animal waste|manure|slurry",{model:"Fertiliser run-off adds nitrates and phosphates to rivers, causing eutrophication, and pesticides and animal waste pollute rivers and groundwater.",tip:"Name the pollutants."}],
["A.4","Outline",2,"Outline integrated drainage basin management (IDBM).","Managing the whole river basin as one unit|whole basin|whole river|one unit|entire","Involving all stakeholders to balance water uses and protect the environment|stakeholders|balance|cooperation|sustainable",{model:"IDBM manages a whole drainage basin as one unit, involving all stakeholders to balance uses such as farming, industry and drinking water while protecting the environment.",tip:"Whole basin + all stakeholders."}],
["A.4","Outline",2,"Outline one advantage of rainwater harvesting.","It collects rain from roofs and stores it for local use|roofs|collect|stores|storage","It is cheap and sustainable, reducing demand on mains water or groundwater|cheap|sustainable|reduces demand|mains|groundwater",{model:"Rainwater harvesting collects rain from roofs for local use, which is cheap and sustainable and reduces demand on mains water and groundwater.",tip:"How it works and why it helps."}],
["B.1","Outline",2,"Outline the effects of El Niño.","Heavy rain and flooding in western South America, such as Peru|peru|flooding|heavy rain|south america","Drought and bushfires in Australia and Indonesia|drought|australia|indonesia|bushfires|wildfires","Fewer fish off Peru as upwelling weakens|fish|anchovy|upwelling",{model:"El Niño brings heavy rain and flooding to Peru and drought and bushfires to Australia and Indonesia.",tip:"Effects on both sides of the Pacific."}],
["B.1","Outline",2,"Outline how the oceans act as a carbon sink.","Carbon dioxide dissolves in seawater|dissolves|absorbed|dissolved","Phytoplankton absorb it, and carbon sinks to the deep ocean in dead organisms|phytoplankton|plankton|biological pump|deep ocean",{model:"Carbon dioxide dissolves in seawater, and phytoplankton absorb it for photosynthesis. When they die, the carbon sinks to the deep ocean.",tip:"Physical and biological processes."}],
["B.2","Outline",2,"Outline how a spit forms.","Longshore drift carries sediment along the coast|longshore drift|carries|transport","Where the coastline changes direction, the sediment is deposited into the sea, building a ridge|deposited|deposition|changes direction|bend|estuary",{model:"Longshore drift carries sediment along the coast. Where the coastline changes direction, for example at an estuary, the sediment is deposited into the sea, building a long ridge.",tip:"Transport, then deposition where the coast turns."}],
["B.2","Distinguish",2,"Distinguish between constructive and destructive waves.","Constructive waves have a strong swash and weak backwash, building up beaches|strong swash|build|deposit|deposition","Destructive waves have a weak swash and strong backwash, eroding beaches|strong backwash|erode|erosion|remove",{model:"Constructive waves have a strong swash and weak backwash, so they deposit material and build beaches. Destructive waves have a strong backwash, so they erode beaches.",tip:"Swash vs backwash decides the effect."}],
["B.3","Outline",2,"Outline one advantage and one disadvantage of a sea wall.","Advantage: it protects property from erosion and flooding|protects|protection|erosion|flooding","Disadvantage: it is very expensive and can increase erosion elsewhere or spoil the beach|expensive|cost|erosion elsewhere|spoils|ugly|scour",{model:"A sea wall protects property behind it from erosion and flooding, but it is very expensive and can cause scouring of the beach in front.",tip:"Label each side."}],
["B.3","Outline",2,"Outline beach nourishment.","Sand or shingle is added to a beach|sand|shingle|added|replenish","To widen it so it absorbs wave energy and protects the coast|wave energy|absorb|widen|protect",{model:"Beach nourishment adds sand or shingle to a beach, widening it so it absorbs more wave energy and protects the coast behind it.",tip:"It's soft engineering: it works with nature."}],
["B.4","Outline",2,"Outline one cause and one effect of ocean acidification.","Cause: the oceans absorb more carbon dioxide, forming carbonic acid|co2|carbon dioxide|carbonic acid","Effect: shell-forming organisms and coral reefs are weakened|coral|shells|shellfish|calcium carbonate|bleaching",{model:"The oceans absorb more CO₂ from the atmosphere, forming carbonic acid. This makes it harder for corals and shellfish to build their calcium carbonate structures.",tip:"Chemistry cause, ecological effect."}],
["B.4","Outline",2,"Outline why overfishing is a problem.","Fish are caught faster than they can reproduce|faster|reproduce|replenish","So stocks collapse, harming food webs and fishing communities|collapse|food web|communities|jobs|livelihoods",{model:"When fish are caught faster than they can reproduce, stocks collapse, as cod did off Newfoundland, harming food webs and the communities that depend on fishing.",tip:"A named example such as the Grand Banks cod helps."}],
["C.1","Outline",2,"Outline why hot deserts have a large daily temperature range.","Skies are clear, with little cloud or moisture|clear skies|no cloud|little cloud|dry|humidity","So the ground heats quickly by day and loses heat quickly at night|loses heat|heat escapes|night|radiation|cold at night",{model:"Desert skies are clear and dry, so the sun heats the ground strongly by day, and with no cloud to trap it, heat escapes quickly at night.",tip:"Clouds are the key: their absence explains both extremes."}],
["C.1","Define",2,"Define permafrost.","Ground that stays frozen|frozen|below 0|below freezing","For at least two consecutive years|two years|2 years|two consecutive",{model:"Permafrost is ground that stays frozen (at or below 0 °C) for at least two consecutive years.",tip:"The two-year rule makes the definition precise."}],
["C.2","Outline",2,"Outline how a barchan sand dune forms.","Wind moves sand by saltation|saltation|wind|transport","Sand is deposited where the wind slows, such as behind an obstacle, building a crescent-shaped dune|deposited|obstacle|crescent|slows",{model:"Wind moves sand by saltation. Where it slows, for example behind an obstacle, sand is deposited, building a crescent-shaped dune whose horns point downwind.",tip:"Transport (saltation), then deposition."}],
["C.2","Outline",2,"Outline how an arête forms.","Two corries erode back to back|two corries|corries|back to back|adjacent","Leaving a sharp, narrow ridge between them|ridge|sharp|narrow|knife edge",{model:"When two corries erode back to back, the land between them is worn into a sharp, narrow ridge called an arête.",tip:"It's what's left between two corries."}],
["C.3","Outline",2,"Outline one way indigenous peoples have adapted to extreme environments.","For example nomadic herding, insulated clothing or homes, or desert irrigation|nomadic|herding|igloos|clothing|irrigation|oases","Letting them survive extreme temperatures and scarce resources|survive|cold|heat|scarce|resources",{model:"The Sami herd reindeer nomadically, moving with the seasons to find grazing, which lets them survive the Arctic's extreme cold and scarce resources.",tip:"Name the people and the adaptation."}],
["C.3","Outline",2,"Outline one impact of mining in a cold environment.","It disturbs fragile ecosystems and the permafrost|permafrost|fragile|ecosystems|habitat","Causing pollution or spills, or conflict with indigenous land use|pollution|spills|indigenous|oil|waste",{model:"Mining disturbs fragile tundra ecosystems and melts permafrost, and spills or pollution can conflict with indigenous herding and hunting.",tip:"Environmental and human impacts."}],
["C.4","Outline",2,"Outline how desertification can be reduced.","Planting trees and vegetation to stabilize the soil, such as the Great Green Wall|planting|trees|vegetation|great green wall","Better land management: less overgrazing and water harvesting|overgrazing|grazing|water harvesting|terracing|management",{model:"Planting trees, as in the Great Green Wall, stabilizes soil, and better land management, such as reducing overgrazing, stops further degradation.",tip:"Planting plus management."}],
["C.4","Outline",2,"Outline why melting Arctic sea ice creates new economic opportunities.","New shipping routes such as the Northern Sea Route|shipping routes|northern sea route|northwest passage|shipping","Access to oil, gas and minerals|oil|gas|minerals|resources",{model:"Melting sea ice opens shipping routes such as the Northern Sea Route, cutting journey times, and gives access to oil, gas and minerals.",tip:"Two separate opportunities."}],
["D.1","Outline",2,"Outline what happens at a constructive (divergent) plate boundary.","The plates move apart|move apart|diverge|apart","Magma rises to fill the gap, forming new crust, ridges and shield volcanoes|magma|new crust|ridge|rift|shield",{model:"At a constructive boundary the plates move apart and magma rises to fill the gap, forming new crust, mid-ocean ridges and shield volcanoes, as in Iceland.",tip:"Movement, then what forms."}],
["D.1","Outline",2,"Outline how a tsunami is generated.","An undersea earthquake suddenly moves the seabed|undersea earthquake|seabed|sea floor","Pushing a huge volume of water upwards, sending waves outwards|water|displaces|waves|volume",{model:"An undersea earthquake suddenly lifts the seabed, pushing a huge volume of water upwards and sending waves racing outwards across the ocean.",tip:"The seabed movement displaces the water."}],
["D.2","Define",2,"Define a pyroclastic flow.","A fast-moving current of hot gas and volcanic material|hot gas|ash|volcanic material|fast","That rushes down the side of a volcano|down|slope|high speed|hundreds",{model:"A pyroclastic flow is a fast-moving current of hot gas, ash and rock that rushes down the side of a volcano at very high speed.",tip:"Hot, fast and ground-hugging."}],
["D.2","Outline",2,"Outline why earthquakes are hard to predict.","Stress builds up in faults without clear warning signs|no warning|warning signs|stress|faults","Possible signals such as foreshocks or radon gas are unreliable|foreshocks|radon|unreliable|inconsistent",{model:"Stress builds up along faults without reliable warning signs; possible signals such as foreshocks or radon gas release don't occur consistently.",tip:"Contrast with forecasting, which is possible."}],
["D.3","Outline",2,"Outline two factors that increase vulnerability to hazards.","Poverty and poor-quality housing|poverty|poor|housing","High population density in hazard zones|population density|densely|crowded","Weak governance, warning systems or emergency services|governance|warning|emergency|corruption","Lack of education and preparation|education|preparation|awareness",{model:"Poverty means poor-quality housing that collapses easily, and weak warning and emergency services mean people can't escape or be rescued in time.",tip:"Explain how each factor raises the risk."}],
["D.3","Explain",2,"Explain why people continue to live near active volcanoes.","The volcanic soils are fertile for farming|fertile|soils|farming","They have jobs in tourism or geothermal energy, or nowhere else to go|tourism|geothermal|jobs|family|nowhere else|cannot afford",{model:"Volcanic soils are very fertile for farming, and tourism and geothermal energy provide jobs, while many people have family ties or cannot afford to move.",tip:"Benefits plus constraints."}],
["D.4","Outline",2,"Outline how land-use zoning reduces hazard risk.","Building is restricted in high-risk areas such as floodplains or near faults|restricted|banned|high risk|avoid","So fewer people and buildings are exposed|fewer people|exposed|exposure|less damage",{model:"Zoning restricts building in high-risk areas such as floodplains or near active faults, so fewer people and buildings are exposed to the hazard.",tip:"Restrict, then reduce exposure."}],
["D.4","Outline",2,"Outline the role of community preparedness in reducing disaster deaths.","Drills, education and evacuation plans mean people know what to do|drills|education|evacuation|plans|training","So they act quickly and more people survive|quickly|saving lives|fewer deaths|survive",{model:"Regular drills, education and evacuation plans, as in Japan, mean people know what to do and act quickly, so more survive.",tip:"Japan's earthquake drills are a strong example."}],
["E.1","Outline",2,"Outline one reason for the growth of ecotourism.","Tourists are more environmentally aware|environmental awareness|aware|green|sustainable","And want authentic nature experiences, which some governments promote|nature|authentic|wildlife|promotion",{model:"Growing environmental awareness means more tourists want low-impact, authentic nature experiences, such as wildlife tourism in Costa Rica, which governments actively promote.",tip:"Demand-side reasons are strongest."}],
["E.1","Define",2,"Define a pleasure periphery.","Tourist destinations far from the tourists' home countries|far|distant|remote","Which grow as travel becomes cheaper and faster|cheaper|faster|travel|flights",{model:"A pleasure periphery is a ring of tourist destinations far from tourists' home countries, which expands as travel becomes cheaper and faster.",tip:"Link it to cheaper, faster travel."}],
["E.2","Outline",2,"Outline one negative impact of tourism on a local area.","For example congestion, litter, pollution or rising house prices|congestion|litter|pollution|house prices|crowding|erosion","Harming residents or the environment|residents|locals|environment|wildlife",{model:"Holiday lets can push up house prices, so local residents can no longer afford to live in the area.",tip:"Say who is harmed and how."}],
["E.2","Outline",2,"Outline one impact of hosting a major sports event.","Investment in infrastructure, jobs and tourism|infrastructure|jobs|tourism|investment|regeneration","But high costs, and stadiums may be left unused afterwards (white elephants)|costs|expensive|white elephant|unused|debt",{model:"Hosting the Olympics can bring investment in transport and regeneration, but costs are high, and some stadiums are left unused afterwards as white elephants.",tip:"A balanced answer earns more credit."}],
["E.3","Outline",2,"Outline why much tourist spending does not benefit local people.","Foreign-owned hotels and tour companies send profits abroad (leakage)|foreign owned|leakage|profits abroad|multinational","Imported food and goods and all-inclusive packages reduce local spending|imported|all inclusive|packages",{model:"Foreign-owned hotels and tour operators send profits abroad (leakage), and all-inclusive packages and imported food mean little money reaches local businesses.",tip:"Use the term economic leakage."}],
["E.3","Outline",2,"Outline one way sport has become globalized.","Global TV and streaming audiences, and sponsorship by TNCs|television|tv|streaming|sponsorship|audiences","International players and clubs with fans worldwide|players|international|fans|worldwide|transfers",{model:"Leagues such as the Premier League are broadcast worldwide and sponsored by TNCs, and clubs sign players and attract fans from all over the world.",tip:"Media, money and migration of players."}],
["E.4","Outline",2,"Outline one strategy for sustainable tourism.","For example limiting visitor numbers, using local guides or eco-certification|limit|quotas|local guides|certification|permits","To protect the environment and benefit local people in the long term|protect|environment|local people|long term",{model:"Limiting visitor numbers with permits, as on the Inca Trail, protects the environment while local guides keep income in the community.",tip:"Strategy, then environmental and local benefit."}],
["E.4","Outline",2,"Outline how technology can help manage tourist numbers.","Online booking and timed tickets spread visitors out|booking|timed tickets|online|apps","Real-time data shows crowded sites so visitors can be redirected|real time|data|redirect|crowding",{model:"Online booking and timed tickets spread visitors through the day, and real-time data can redirect people away from crowded sites.",tip:"Give specific technologies."}],
["F.1","Define",2,"Define food security.","When all people have reliable access to enough food|access|sufficient|enough","That is safe and nutritious, at all times|nutritious|safe|all times|healthy",{model:"Food security exists when all people, at all times, have reliable access to enough safe and nutritious food.",tip:"Access, sufficiency and nutrition."}],
["F.1","Outline",2,"Outline one reason why life expectancy varies between countries.","Differences in healthcare, sanitation and clean water|healthcare|sanitation|clean water|hospitals","And in diet, income and disease|diet|income|disease|poverty",{model:"Countries with good healthcare, sanitation and clean water have far fewer deaths from infectious disease, so life expectancy is higher.",tip:"Name the factor and link it to deaths."}],
["F.2","Outline",2,"Outline relocation diffusion of a disease.","Infected people move or travel to a new area|move|travel|migrate","Carrying the disease to places far from where it started|new area|far|origin|carry",{model:"In relocation diffusion, infected people travel or migrate and carry the disease to places far from where it began, as when Ebola reached new countries by air travel.",tip:"Contrast with contagious diffusion, which spreads to neighbours."}],
["F.2","Outline",2,"Outline one environmental impact of intensive farming.","Fertiliser and pesticide run-off pollutes rivers|run off|runoff|rivers|pollute","Monocultures and hedgerow removal reduce biodiversity and soil quality|monoculture|monocultures|biodiversity|hedgerows|soil",{model:"Fertiliser and pesticide run-off pollutes rivers, and large monocultures with hedgerows removed reduce biodiversity and soil quality.",tip:"Name the practice and its effect."}],
["F.3","Outline",2,"Outline the role of NGOs in food and health.","They provide aid, food or medical care in emergencies|aid|medical|emergency|relief","And run long-term projects such as vaccination or farmer training, and campaign|vaccination|training|projects|campaign|education",{model:"NGOs such as Médecins Sans Frontières provide medical care and food in emergencies and run long-term projects such as vaccination and farmer training.",tip:"Emergency and long-term roles."}],
["F.3","Outline",2,"Outline how governments can reduce obesity.","Sugar taxes, or regulating food advertising and labelling|sugar tax|tax|advertising|regulation|labelling","Education campaigns and promoting exercise|education|campaign|exercise|sport",{model:"Governments can introduce sugar taxes and restrict junk-food advertising, and run education campaigns that promote healthy eating and exercise.",tip:"Policy plus education."}],
["F.4","Outline",2,"Outline one way to reduce food waste.","Better storage and transport, especially in low-income countries|storage|refrigeration|transport","Changing consumer behaviour, such as planning meals or using leftovers|consumers|leftovers|best before|planning|donate",{model:"Better refrigerated storage reduces losses after harvest, and consumers can plan meals and use leftovers to waste less.",tip:"Waste happens at different stages: say which you target."}],
["F.4","Outline",2,"Outline why vertical farming may help future food security.","Crops are grown indoors in stacked layers, using very little land|indoors|stacked|layers|little land","Allowing year-round production close to cities with less water|year round|cities|less water|local",{model:"Vertical farms grow crops indoors in stacked layers, using little land and less water, and produce food all year close to the cities that need it.",tip:"Land, water and location advantages."}],
["G.1","Outline",2,"Outline the characteristics of an informal settlement.","Self-built housing on land without legal rights|self built|illegal|no legal|squatter","Lacking basic services such as clean water, sanitation and electricity|clean water|sanitation|electricity|services",{model:"Informal settlements are self-built homes on land without legal rights, often lacking clean water, sanitation and electricity.",tip:"Housing, legal status and services."}],
["G.1","Define",2,"Define urban sprawl.","The spread of a city into the surrounding rural area|spread|rural|outwards|countryside","Usually low-density, car-dependent development|low density|car|suburbs",{model:"Urban sprawl is the outward spread of a city into the surrounding countryside, usually as low-density, car-dependent suburbs.",tip:"Mention low density."}],
["G.2","Outline",2,"Outline why reurbanization happens.","Regeneration of inner-city areas and new housing|regeneration|redevelopment|new housing|brownfield","Which attracts young professionals with jobs and amenities|young professionals|jobs|amenities|nightlife|gentrification",{model:"Regeneration of run-down inner-city areas brings new housing, which attracts young professionals who want to live near jobs and amenities.",tip:"Cause (regeneration) and who moves back."}],
["G.2","Define",2,"Define a megacity.","A city with more than 10 million people|10 million|ten million","Many are in low- and middle-income countries, such as Lagos or Dhaka|lagos|dhaka|mumbai|tokyo|delhi|example",{model:"A megacity is a city with over 10 million people, such as Lagos, Dhaka or Tokyo.",tip:"Give the threshold and an example."}],
["G.3","Outline",2,"Outline one cause and one effect of urban air pollution.","Cause: vehicle exhaust, industry or burning fuels|vehicles|exhaust|traffic|industry|burning","Effect: respiratory illnesses such as asthma, and smog|respiratory|asthma|smog|lung|health",{model:"Vehicle exhaust and industry release pollutants that cause smog and respiratory illnesses such as asthma.",tip:"One cause and one effect, clearly linked."}],
["G.3","Outline",2,"Outline why informal settlements are vulnerable to hazards.","They are often built on unsafe land, such as steep slopes or floodplains|steep|slopes|floodplain|unsafe|hillsides","With poor-quality housing and few services or emergency access|poor quality|flimsy|services|emergency",{model:"Informal settlements are often built on steep slopes or floodplains with flimsy housing, and narrow streets and few services make emergency response difficult.",tip:"Location plus construction."}],
["G.4","Outline",2,"Outline one way to make urban transport more sustainable.","For example public transport, cycle lanes or congestion charges|public transport|cycle|cycling|congestion charge|trams|buses|metro","Reducing car use, emissions and congestion|car use|emissions|congestion|pollution",{model:"Cities can invest in public transport and cycle lanes, which reduces car use, emissions and congestion, as in Copenhagen.",tip:"Strategy plus environmental benefit."}],
["G.4","Outline",2,"Outline the purpose of a smart city.","It uses digital technology and data to manage services|digital|data|sensors|technology","To improve efficiency, sustainability and quality of life|efficiency|sustainable|quality of life|traffic|energy",{model:"A smart city uses sensors and data to manage services such as traffic and energy, improving efficiency, sustainability and quality of life.",tip:"How it works and what it improves."}],
]);

/* ---------- a third set: every topic now has at least eight questions ---------- */
QB("geo", [
["1.1","Define",2,"Define total fertility rate.","The average number of children born to a woman|average number of children|children per woman|births per woman","Over her lifetime, if current rates continue|lifetime|reproductive life|childbearing years",{model:"The total fertility rate is the average number of children a woman would have over her lifetime at current rates.",tip:"Replacement level is about 2.1."}],
["1.1","Define",2,"Define replacement-level fertility.","The fertility rate at which a population exactly replaces itself|replace itself|stays the same size|stable|same size","About 2.1 children per woman|2.1",{model:"Replacement-level fertility is about 2.1 children per woman, the rate at which a population replaces itself without migration.",tip:"Slightly above 2 because some children die."}],
["1.1","Outline",2,"Outline one reason why birth rates fall as countries develop.","Better access to contraception and education for women|contraception|education|women|family planning|careers","Lower infant mortality, and children cost more in urban areas|infant mortality|fewer children needed|cost|expensive|urban",{model:"As countries develop, women gain education and access to contraception, and lower infant mortality means fewer births are needed.",tip:"Stage 3 of the DTM."}],
["1.1","Outline",2,"Outline the core–periphery pattern of economic development.","Wealth, investment and power are concentrated in core regions|wealth|concentrated|richer|investment|wealthy","Peripheral regions are poorer and lose labour and raw materials to the core|poorer|less developed|labour|labor|raw materials|migrants",{model:"Wealth and investment concentrate in core regions, while poorer peripheral regions supply labour and raw materials to the core.",tip:"Can apply at global or national scale."}],
["1.2","Define",2,"Define net migration.","Immigration minus emigration|immigration minus emigration|immigrants minus emigrants|in minus out|arrivals minus departures","For a place over a period, usually a year|per year|year|period|per 1000",{model:"Net migration is immigration minus emigration for a place over a period, usually a year.",tip:"Can be positive or negative."}],
["1.2","Outline",2,"Outline one positive and one negative impact of immigration on a host country.","Positive: fills labour shortages and adds skills|labour shortages|labor shortages|skills|young workers|workforce","Negative: can increase pressure on housing and services, or social tension|pressure|housing|services|tension",{model:"Immigrants fill labour shortages and add skills, but rapid immigration can increase pressure on housing and services.",tip:"One of each."}],
["1.2","Outline",2,"Outline what is meant by rural–urban migration.","People moving from the countryside to towns and cities|countryside|rural areas to|villages to|from the country","For jobs, services and better living standards|jobs|services|education|healthcare|living standards",{model:"Rural–urban migration is people moving from the countryside to cities for jobs, services and better living standards.",tip:"A cause of rapid urbanization."}],
["1.2","Define",2,"Define a refugee.","A person forced to leave their country|forced|flee|fled|leave their country","Because of persecution, war or violence, who cannot safely return|persecution|war|conflict|violence|well founded fear",{model:"A refugee is a person forced to flee their country because of persecution, war or violence, and who cannot safely return.",tip:"Compare with an IDP."}],
["1.3","Outline",2,"Outline China's one-child policy and its effects.","From 1979 most families were restricted to a single child, enforced with fines|1979|limited|restricted|fines|penalties","It lowered fertility but caused a gender imbalance and rapid ageing|gender imbalance|more boys|ageing|aging|4 2 1",{model:"From 1979 most families were restricted to one child, enforced with fines; it cut fertility but caused a gender imbalance and rapid ageing.",tip:"Ended in 2015."}],
["1.3","Outline",2,"Outline one way a government can respond to an ageing population.","Raise the retirement age or encourage immigration|retirement age|immigration|migrants|pension","To keep enough workers paying tax for pensions and healthcare|workers|pensions|tax|healthcare|workforce",{model:"Raising the retirement age keeps more people working and paying tax, helping fund pensions and healthcare.",tip:"Response plus why."}],
["1.3","Outline",2,"Outline one challenge of a youthful population.","High demand for schools and jobs|schools|education|jobs|employment","Putting pressure on government budgets and services|pressure|budgets|services|unemployment",{model:"A youthful population needs many school places and jobs, putting pressure on government budgets and risking unemployment.",tip:"Challenge plus consequence."}],
["1.3","Outline",2,"Outline how a demographic dividend can benefit a country.","A large working-age population compared with dependants|working age|large workforce|fewer dependants|fewer dependents","Can boost economic growth if there are enough jobs and education|economic growth|growth|productivity|savings",{model:"When the working-age population is large compared with dependants, output and savings can rise, boosting economic growth if there are jobs.",tip:"East Asia is the classic example."}],
["2.1","Outline",2,"Outline the role of methane in climate change.","A greenhouse gas released by cattle, rice paddies, landfill and wetlands|cattle|livestock|rice|landfill|wetlands","It traps far more heat per molecule than CO₂|more heat|more powerful|stronger|traps",{model:"Methane from cattle, rice paddies and landfill is a greenhouse gas that traps far more heat per molecule than CO₂.",tip:"Short-lived but powerful."}],
["2.1","Define",2,"Define the global energy balance.","The balance between incoming shortwave solar radiation|incoming|solar|shortwave|sun","And outgoing longwave (infrared) radiation from the Earth|outgoing|longwave|infrared|reradiated",{model:"The global energy balance is the balance between incoming shortwave solar radiation and outgoing longwave radiation from the Earth.",tip:"Imbalance → warming or cooling."}],
["2.1","Outline",2,"Outline one natural factor that changes the Earth's climate.","E.g. Milankovitch cycles, solar output or volcanic eruptions|milankovitch|orbit|solar output|sunspots|volcanic|volcanoes","Changing how much solar energy reaches or is blocked from the surface|energy|radiation|sunlight|ash|aerosols|cooling",{model:"Large volcanic eruptions release aerosols that block sunlight, cooling the climate for a year or two.",tip:"Factor plus mechanism."}],
["2.1","Outline",2,"Outline the ice–albedo feedback.","Warming melts ice and snow, exposing darker land or sea|melts|ice|snow|darker|exposed","Which absorbs more radiation, causing further warming|absorbs more|more warming|further warming|less reflected",{model:"Warming melts ice and snow, exposing darker surfaces that absorb more radiation, causing further warming.",tip:"A positive feedback."}],
["2.2","Outline",2,"Outline how climate change affects extreme weather.","Warmer air holds more moisture and warmer oceans supply more energy|warmer|moisture|ocean temperatures|energy","So heatwaves, droughts, floods and storms become more frequent or intense|heatwaves|droughts|floods|storms|hurricanes|intense|frequent",{model:"Warmer air holds more moisture and warmer oceans give storms more energy, so heatwaves, floods and intense storms become more frequent.",tip:"Mechanism plus effect."}],
["2.2","Outline",2,"Outline one impact of climate change on human health.","Heat stress, or the spread of diseases such as malaria|heat|heatstroke|malaria|dengue|disease|mosquitoes","As warmer temperatures extend the range of disease vectors or cause heatwaves|vectors|range|heatwaves|warmer|new areas",{model:"Warmer temperatures let mosquitoes spread malaria and dengue into new areas, and heatwaves cause heat stress.",tip:"Impact plus cause."}],
["2.2","Outline",2,"Outline why glacier retreat threatens water supplies.","Glaciers store water and release meltwater in dry seasons|store|meltwater|dry season|summer","As they shrink, the rivers they feed will carry less water, e.g. in the Himalayas|rivers|himalayas|andes|shortages|less water",{model:"Glaciers store water and release it in dry seasons; as they shrink, rivers fed by them, such as in the Himalayas, will carry less water.",tip:"Short-term floods, long-term shortage."}],
["2.2","Define",2,"Define climate refugees.","People forced to leave their homes|forced|displaced|move|leave their homes","Because of climate impacts such as sea-level rise or drought|sea level rise|drought|desertification|flooding|climate change",{model:"Climate refugees are people forced to leave their homes because of climate impacts such as sea-level rise or drought.",tip:"Not a legal refugee category."}],
["2.3","Outline",2,"Outline the Paris Agreement (2015).","Countries agreed to limit warming to well below 2 °C, aiming for 1.5 °C|1.5|well below 2|limit warming","Each country sets its own emissions targets (NDCs) and reviews them|ndc|ndcs|nationally determined|own targets|pledges",{model:"In the Paris Agreement countries agreed to keep warming well below 2 °C, aiming for 1.5 °C, with each setting its own targets (NDCs).",tip:"Targets aren't legally binding."}],
["2.3","Outline",2,"Outline geoengineering as a response to climate change.","Large-scale, deliberate intervention in the climate system|large scale|deliberate|intervention|technology","E.g. carbon capture and storage or solar radiation management|carbon capture|ccs|solar radiation management|aerosols|mirrors|ocean fertilisation|ocean fertilization",{model:"Geoengineering is deliberate large-scale intervention in the climate, such as carbon capture or reflecting sunlight with aerosols.",tip:"Risky and unproven at scale."}],
["2.3","Outline",2,"Outline one way individuals can reduce their carbon footprint.","E.g. using public transport, eating less meat or saving energy at home|public transport|cycling|less meat|insulation|energy|flying less","Reducing the greenhouse gases their lifestyle produces|greenhouse gases|reduces emissions|reduce emissions|cuts emissions|less co2|fewer emissions|lower emissions",{model:"Using public transport instead of a car reduces the greenhouse gases an individual's lifestyle produces.",tip:"Action plus effect."}],
["2.3","Outline",2,"Outline why international agreement on climate change is difficult.","Countries disagree over who should cut emissions and who should pay|disagree|responsibility|who pays|historic|fairness","Developing countries want to grow, and cuts may harm economies|economic growth|develop|costs|economies|jobs",{model:"Countries disagree over responsibility and who pays, and developing countries fear cuts will harm their growth.",tip:"Equity and economics."}],
["3.1","Define",2,"Define the Gini coefficient.","A measure of income inequality|inequality|income distribution|unequal","From 0 (perfect equality) to 1 (perfect inequality)|0 to 1|perfect equality|perfect inequality",{model:"The Gini coefficient measures income inequality from 0 (perfect equality) to 1 (perfect inequality).",tip:"Higher = more unequal."}],
["3.1","Outline",2,"Outline two limitations of GNI per capita as a measure of development.","It is an average that hides inequality|average|hides inequality|inequality|distribution","It ignores non-monetary factors such as health and education, and the informal economy|health|education|quality of life|informal|non monetary",{model:"GNI per capita is an average that hides inequality and ignores non-monetary factors such as health and education.",tip:"Why HDI was created."}],
["3.1","Outline",2,"Outline why ecological footprints are larger in high-income countries.","Higher consumption of goods, energy and food|consumption|consume more|more energy|meat|goods","Including more car use, flying and waste|cars|flying|waste|travel|imports",{model:"High-income countries consume more goods, energy and meat, with more car use, flying and waste.",tip:"Footprint grows with wealth."}],
["3.1","Distinguish",2,"Distinguish between renewable and non-renewable resources.","Renewable resources are naturally replenished, e.g. wind or solar energy|replenished|replaced|won t run out|wind|solar","Non-renewable resources are finite and will run out, e.g. oil or coal|finite|run out|oil|coal|fossil",{model:"Renewable resources such as wind are naturally replenished; non-renewable resources such as oil are finite and will run out.",tip:"Give an example of each."}],
["3.2","Define",2,"Define a country's energy mix.","The combination of energy sources a country uses|combination|sources|proportion|share","E.g. fossil fuels, nuclear and renewables|fossil|nuclear|renewables|coal|wind|solar",{model:"The energy mix is the combination of energy sources a country uses, such as fossil fuels, nuclear and renewables.",tip:"Often shown as percentages."}],
["3.2","Outline",2,"Outline one advantage and one disadvantage of hydroelectric power.","Advantage: renewable, low-carbon and reliable|renewable|low carbon|no emissions|reliable|clean","Disadvantage: floods land, displaces people and damages river ecosystems|flooding|floods|displaced|displacement|ecosystems|expensive|sediment",{model:"Hydroelectric power is renewable and low-carbon, but reservoirs flood land, displacing people and damaging ecosystems.",tip:"One of each."}],
["3.2","Outline",2,"Outline the impacts of land grabbing.","Large areas of land in poorer countries are bought or leased by foreign investors|foreign|investors|bought|leased|large areas","Local farmers may lose their land, reducing local food security|lose land|displaced|food security|evicted|local farmers",{model:"Foreign investors buy or lease large areas of land in poorer countries, and local farmers may be evicted, reducing food security.",tip:"Often for food or biofuels."}],
["3.2","Outline",2,"Outline what is meant by virtual water.","The water used to produce a product|water used to produce|water needed to produce|water used in|embedded|hidden water","So trade in goods such as food also moves water between countries|traded|trade in|trading|imported|exported|imports|exports",{model:"Virtual water is the water used to produce a product, so trading goods such as food also moves water between countries.",tip:"A kilogram of beef needs about 15 000 litres."}],
["3.3","Define",2,"Define sustainable development.","Development that meets the needs of the present|needs of the present|present needs|today","Without compromising the ability of future generations to meet their own needs|future generations|future",{model:"Sustainable development meets the needs of the present without compromising the ability of future generations to meet their own.",tip:"The Brundtland definition."}],
["3.3","Outline",2,"Outline one way to increase food production sustainably.","E.g. precision farming, drip irrigation or agroforestry|precision|drip|agroforestry|crop rotation|organic|gm crops","Raising yields while protecting soil and water|yields|soil|water|less fertiliser|less fertilizer",{model:"Drip irrigation delivers water straight to roots, raising yields while saving water.",tip:"Method plus benefit."}],
["3.3","Outline",2,"Outline the role of NGOs in resource stewardship.","They campaign, educate and run conservation projects|campaign|educate|awareness|projects|conservation","E.g. WWF or Greenpeace|wwf|greenpeace|oxfam|wateraid",{model:"NGOs such as WWF campaign, raise awareness and run conservation projects.",tip:"Name an NGO."}],
["3.3","Outline",2,"Outline how a carbon tax encourages resource stewardship.","It makes polluting activities more expensive|more expensive|costs more|price on carbon|charge for carbon|polluting costs","So firms and people switch to cleaner energy and cut emissions|switch|cleaner energy|cleaner fuels|renewables|reduce emissions|cut emissions",{model:"A carbon tax makes polluting more expensive, so firms and people switch to cleaner energy and cut emissions.",tip:"Market-based policy."}],
["4.1","Outline",2,"Outline one example of soft power.","E.g. culture, films, music, education or aid|culture|films|hollywood|music|k pop|universities|aid","Which makes other countries admire or align with the country|attract|influence|admire|persuade|appeal",{model:"South Korea's K-pop and films spread its culture worldwide, increasing its influence and appeal.",tip:"Attraction, not force."}],
["4.1","Outline",2,"Outline the role of the UN Security Council.","It can authorize sanctions, peacekeeping or military action to maintain peace|peace|sanctions|peacekeeping|military action","Its five permanent members each have a veto|veto|five permanent|p5",{model:"The Security Council can authorize sanctions and peacekeeping to maintain peace, but each of its five permanent members has a veto.",tip:"The veto limits its power."}],
["4.1","Outline",2,"Outline the rise of China as a global power.","Rapid economic growth based on manufacturing and exports|economic growth|manufacturing|exports|economy","Growing global influence through the Belt and Road Initiative and investment|belt and road|bri|investment|loans|africa",{model:"China's manufacturing-led growth made it the world's second-largest economy, and the Belt and Road Initiative extends its influence.",tip:"Economic and political."}],
["4.1","Define",2,"Define hard power.","Using military force or economic pressure|military|force|economic pressure|sanctions","To make other countries act in a certain way|make other countries|act in a certain way|coerce|compel|make them",{model:"Hard power is using military force or economic pressure to make other countries act in a certain way.",tip:"Coercion versus attraction."}],
["4.2","Outline",2,"Outline the role of transnational corporations (TNCs) in global networks.","They link countries through production, trade and investment|production|trade|investment|fdi|supply chains","Moving goods, money, technology and jobs across borders|jobs|technology|money|across borders|globally",{model:"TNCs link countries through production and investment, moving goods, money, technology and jobs across borders.",tip:"Name a TNC."}],
["4.2","Outline",2,"Outline why remittances matter to some countries.","They form a large share of GDP in countries such as Nepal or Tajikistan|gdp|share|large|nepal|tajikistan|philippines","Paying for families' food, education and healthcare|families|food|education|healthcare|poverty",{model:"In countries like Nepal remittances are a large share of GDP and pay for families' food, education and healthcare.",tip:"A financial flow."}],
["4.2","Outline",2,"Outline the role of containerization in global trade.","Standard shipping containers made loading faster and cheaper|faster|cheaper|standard|loading","Greatly reducing transport costs and boosting trade|transport costs|reduced costs|lower costs|cutting costs|more trade|boosting trade|boosted trade",{model:"Standard containers made loading faster and cheaper, greatly cutting transport costs and boosting global trade.",tip:"A key technology of globalization."}],
["4.2","Outline",2,"Outline how global data flows have grown.","Internet use and cloud services send vast amounts of data across borders|internet|cloud|online|data centres|streaming","Through submarine cables and satellites that link economies|submarine cables|cables|satellites|fibre|fiber",{model:"Internet and cloud use send huge amounts of data across borders through submarine cables and satellites.",tip:"The fastest-growing flow."}],
["4.3","Outline",2,"Outline how trade blocs affect global interactions.","Removing trade barriers between members increases trade among them|removing barriers|free trade|tariffs|increase trade","But may reduce trade with non-members|non members|outside|external tariff|exclude",{model:"Trade blocs remove barriers between members, increasing trade among them, but may reduce trade with outsiders.",tip:"E.g. the EU or ASEAN."}],
["4.3","Outline",2,"Outline one political factor that limits global interactions.","E.g. tariffs, sanctions, migration controls or censorship|tariffs|sanctions|migration controls|visa|censorship|firewall","Which reduce flows of goods, people or information|reduce flows|restrict|limit|block",{model:"China's internet censorship blocks many foreign websites, limiting flows of information.",tip:"Factor plus effect."}],
["4.3","Define",2,"Define the digital divide.","The gap between people with and without internet access|gap|access|without|have and have not","Between countries or groups, e.g. rich and poor or urban and rural|rich and poor|urban and rural|countries|groups",{model:"The digital divide is the gap in internet access between countries or groups, such as rich and poor or urban and rural.",tip:"Access, skills and cost."}],
["4.3","Outline",2,"Outline one way the COVID-19 pandemic affected global interactions.","Border closures and travel restrictions reduced flows of people|border closures|travel restrictions|lockdowns|flights","Supply chains were disrupted, while digital interactions grew|supply chains|disrupted|shortages|online|digital",{model:"Border closures cut the movement of people, supply chains were disrupted, and online interaction grew.",tip:"Several flows changed."}],
["5.1","Outline",2,"Outline how education supports development.","It raises skills and productivity, increasing incomes|skills|productivity|incomes|jobs","Especially girls' education, which lowers fertility and improves health|girls|women|fertility|health|empowerment",{model:"Education raises skills and incomes, and educating girls also lowers fertility and improves family health.",tip:"Economic and social benefits."}],
["5.1","Outline",2,"Outline one advantage and one disadvantage of microfinance.","Advantage: lets poor people, often women, start small businesses|start businesses|small businesses|women|poor|entrepreneurs","Disadvantage: high interest rates can trap borrowers in debt|high interest|debt|repay|default",{model:"Microfinance lets poor people, often women, start small businesses, but high interest rates can trap borrowers in debt.",tip:"E.g. Grameen Bank."}],
["5.1","Outline",2,"Outline the role of debt relief in development.","Cancelling or reducing poor countries' debts|cancel|cancelling|reduce debts|write off|hipc","Freeing money for health and education|health|education|services|spending",{model:"Debt relief cancels or reduces poor countries' debts, freeing money to spend on health and education.",tip:"E.g. the HIPC initiative."}],
["5.1","Distinguish",2,"Distinguish between top-down and bottom-up development.","Top-down: large projects planned by governments or agencies|governments|large projects|planned|dams|agencies","Bottom-up: small, local projects involving communities|local|small scale|communities|grassroots|ngos",{model:"Top-down development is large projects planned by governments, such as dams; bottom-up development is small local projects run with communities.",tip:"Scale and who decides."}],
["5.2","Outline",2,"Outline what is meant by cultural imperialism.","One culture, often Western or American, dominates others|dominates|western|american|dominant","Through media, brands and products, eroding local cultures|media|brands|films|erode|loss of local|homogeni",{model:"Cultural imperialism is when a dominant culture, often American, spreads through media and brands, eroding local cultures.",tip:"Linked to homogenization."}],
["5.2","Outline",2,"Outline cultural hybridity.","The mixing of cultural traits from different places|mix|mixing|blend|fusion","Creating new forms, e.g. in food or music|new forms|food|music|cuisine",{model:"Cultural hybridity is the mixing of traits from different cultures, creating new forms such as fusion food or music.",tip:"Globalization can create, not just erase."}],
["5.2","Outline",2,"Outline how migrants maintain their identity in a new country.","Diaspora communities keep their language, religion, food and festivals|language|religion|food|festivals|traditions","Through community groups, media and links with home|community groups|community centres|social media|links with home|networks|diaspora",{model:"Diaspora communities keep their language, religion and festivals alive through community groups and links with home.",tip:"Think of a named diaspora."}],
["5.2","Outline",2,"Outline one way governments protect national culture.","E.g. quotas for local films or music, or language laws|quotas|language laws|subsidies|bans|protect","Reducing the dominance of foreign media|foreign media|foreign|reduce|limit",{model:"France sets quotas for French-language music on radio, reducing the dominance of foreign media.",tip:"Policy plus aim."}],
["5.3","Outline",2,"Outline one reason for the rise of nationalism in response to globalization.","Fear of job losses to globalization|jobs|job losses|unemployment|deindustrialization","Or concern about immigration and loss of national identity or sovereignty|immigration|identity|sovereignty|control",{model:"Job losses from globalization and concern about immigration and identity have fuelled nationalist movements.",tip:"E.g. Brexit."}],
["5.3","Outline",2,"Outline what is meant by localism.","Supporting local businesses, food and decision-making|local businesses|local food|local produce|local decision","To keep money and control within the community|community|money stays|keep money|control|resilience",{model:"Localism means supporting local businesses and decision-making so money and control stay in the community.",tip:"A response to globalization."}],
["5.3","Outline",2,"Outline how civil society organizations respond to globalization.","NGOs and campaign groups protest or lobby|ngos|protest|lobby|campaign","For fair trade, workers' rights or environmental protection|fair trade|workers rights|labour rights|environment|climate",{model:"NGOs and campaign groups lobby and protest for fair trade, workers' rights and environmental protection.",tip:"Who and for what."}],
["5.3","Outline",2,"Outline one way consumers can respond to global issues.","Buying fair trade or ethical products, or boycotting brands|fair trade|ethical|boycott|organic","Putting pressure on companies to change|pressure|change|demand",{model:"Consumers can buy fair-trade products or boycott unethical brands, pressuring companies to change.",tip:"Consumer power."}],
["6.1","Outline",2,"Outline how trade wars affect global interactions.","Countries raise tariffs on each other's goods|tariffs|tariff|taxes on imports","Reducing trade and raising prices for consumers|reduce trade|less trade|higher prices|prices",{model:"In a trade war countries raise tariffs on each other's goods, reducing trade and raising prices.",tip:"E.g. US–China from 2018."}],
["6.1","Outline",2,"Outline why armed conflict disrupts global interactions.","War damages infrastructure and blocks trade routes|infrastructure|trade routes|blocked|damage","Causing refugees, sanctions and higher food and energy prices, e.g. after the invasion of Ukraine|refugees|sanctions|energy prices|food prices|ukraine",{model:"War damages infrastructure and blocks trade routes, causing refugees and higher food and energy prices, as after the invasion of Ukraine.",tip:"Local war, global effects."}],
["6.1","Outline",2,"Outline the risk of financial contagion.","A crisis in one country's financial system spreads to others|spreads|spread|other countries","Because banks and markets are interconnected, e.g. the 2008 global financial crisis|interconnected|linked|2008|banks|global financial crisis",{model:"Because banks and markets are interconnected, a crisis in one country can spread to others, as in 2008.",tip:"Interdependence is the risk."}],
["6.1","Outline",2,"Outline why depending on a single supplier is a risk.","Disruption at that supplier cuts off supply|disruption|shortage|stops|cut off","E.g. Europe's dependence on Russian gas, or on Taiwan for chips|russian gas|gas|semiconductors|taiwan|rare earths",{model:"Any disruption at a single supplier cuts off supply, as Europe found with Russian gas.",tip:"Diversify suppliers."}],
["6.2","Outline",2,"Outline acid rain as a transboundary pollution issue.","Sulfur dioxide and nitrogen oxides from one country are carried by winds|sulfur dioxide|so2|nitrogen oxides|winds|carried","They fall as acid rain in other countries, damaging lakes and forests|other countries|lakes|forests|neighbouring|scandinavia",{model:"Sulfur dioxide and nitrogen oxides from one country are carried by winds and fall as acid rain elsewhere, damaging lakes and forests.",tip:"Polluter and victim differ."}],
["6.2","Outline",2,"Outline the tragedy of the commons.","Shared resources are overused because individuals act in their own interest|overused|overuse|self interest|shared","E.g. overfishing of the high seas|overfishing|high seas|atmosphere|fish",{model:"When a resource is shared, individuals act in their own interest and overuse it, as with overfishing on the high seas.",tip:"Hardin, 1968."}],
["6.2","Outline",2,"Outline how invasive species spread through global networks.","Carried in ships' ballast water, cargo or by travellers|ballast|cargo|shipping|travellers|trade","They can outcompete native species and damage ecosystems|outcompete|native species|ecosystems|biodiversity",{model:"Invasive species travel in ballast water and cargo, then outcompete native species and damage ecosystems.",tip:"E.g. zebra mussels."}],
["6.2","Outline",2,"Outline the role of international agreements in managing transboundary pollution.","Countries agree shared limits, e.g. the Montreal Protocol on CFCs|montreal|cfcs|agreements|limits|marpol","Because no single country can solve it alone|no single country|no country|alone|together|cooperation|cross borders",{model:"Because no country can solve transboundary pollution alone, agreements such as the Montreal Protocol set shared limits.",tip:"Montreal is the success story."}],
["6.3","Outline",2,"Outline how diversifying an economy increases resilience.","Relying on many industries and trading partners|many industries|several|range|different sectors|partners","So a shock to one doesn't cripple the economy|shock|less vulnerable|spreads risk|reduce risk",{model:"An economy with many industries and partners is less vulnerable, because a shock to one sector doesn't cripple it.",tip:"Don't rely on one export."}],
["6.3","Outline",2,"Outline the role of stockpiles in resilience.","Reserves of essential goods such as food, fuel or medicines|reserves|food|fuel|medicines|oil","Which can be used during supply disruptions|disruption|crisis|shortages|emergency",{model:"Stockpiles of essentials such as fuel and medicines can be used when supply is disrupted.",tip:"E.g. strategic oil reserves."}],
["6.3","Outline",2,"Outline one way communities build resilience to global shocks.","Local food production, renewable energy or mutual-aid networks|local food|renewable|community|networks|cooperatives","Reducing dependence on global supply chains|dependence|supply chains|self sufficient|self reliant",{model:"Growing food locally and using community renewable energy reduce dependence on global supply chains.",tip:"Local action."}],
["6.3","Define",2,"Define nearshoring.","Moving production to a nearby country|nearby|neighbouring|closer|neighboring","To shorten supply chains and reduce risk|shorten|shorter supply chains|risk|transport",{model:"Nearshoring is moving production to a nearby country to shorten supply chains and reduce risk.",tip:"Compare with reshoring."}],
]);

QB("geo", [
["A.1","Distinguish",2,"Distinguish between infiltration and percolation.","Infiltration: water soaking into the soil from the surface|into the soil|soaks into|enters the soil|from the surface","Percolation: water moving down through the soil into the rock below|into the rock|into rock|bedrock|groundwater|deeper|underlying",{model:"Infiltration is water soaking into the soil from the surface; percolation is water moving down through the soil into the rock below.",tip:"Surface → soil → rock."}],
["A.1","Outline",2,"Outline how a waterfall forms.","Where hard rock overlies soft rock, the soft rock is eroded faster|hard rock|soft rock|resistant|less resistant","Undercutting leaves an overhang that collapses, so the waterfall retreats upstream, leaving a gorge|undercut|overhang|collapses|retreats|gorge|plunge pool",{model:"Where hard rock lies over soft rock, the soft rock erodes faster, undercutting the hard rock; the overhang collapses and the waterfall retreats upstream, forming a gorge.",tip:"Include the plunge pool."}],
["A.1","Outline",2,"Outline the processes of river erosion.","Hydraulic action and abrasion|hydraulic action|abrasion|corrasion","Attrition and solution (corrosion)|attrition|solution|corrosion",{model:"Rivers erode by hydraulic action and abrasion, while attrition wears down the load and solution dissolves rock.",tip:"Four processes."}],
["A.1","State",2,"State two stores in the drainage basin system.","Interception, surface storage or soil water|interception|surface storage|soil water|soil moisture|vegetation","Groundwater or channel storage|groundwater|channel storage|river channel|aquifer",{model:"Soil water and groundwater.",tip:"Stores hold water; flows move it."}],
["A.2","Define",2,"Define bankfull discharge.","The maximum discharge a river channel can carry|maximum discharge|maximum flow|most water|full capacity","Without overflowing its banks|without overflowing|without flooding|before flooding|before it floods",{model:"Bankfull discharge is the maximum discharge a channel can carry without overflowing its banks.",tip:"Above it, the river floods."}],
["A.2","Outline",2,"Outline how urbanization increases flood risk.","Impermeable surfaces such as concrete and tarmac reduce infiltration|impermeable|concrete|tarmac|less infiltration","Drains carry water quickly to rivers, so lag time falls and peak discharge rises|drains|shorter lag time|lag time|higher peak|peak discharge",{model:"Concrete and tarmac reduce infiltration, and drains carry water quickly to rivers, shortening lag time and raising peak discharge.",tip:"Link to the hydrograph."}],
["A.2","Outline",2,"Outline one physical factor that increases flood risk.","Steep slopes, impermeable rock, saturated soil or intense rainfall|steep|impermeable rock|saturated|intense rainfall|heavy rain|snowmelt|clay","Increasing surface runoff, so water reaches the river quickly|surface runoff|overland flow|runoff|reaches the river",{model:"Saturated soil can't absorb more rain, so surface runoff increases and water reaches the river quickly.",tip:"Factor plus mechanism."}],
["A.2","Outline",2,"Outline one soft engineering strategy for flood management.","E.g. afforestation, wetland restoration or floodplain zoning|afforestation|planting trees|wetland|floodplain zoning|land use zoning|river restoration","Which slows runoff or keeps building out of flood-prone areas|slows|interception|stores water|away from|lower damage",{model:"Planting trees in the upper basin increases interception and slows runoff, reducing flood peaks.",tip:"Works with natural processes."}],
["A.3","Outline",2,"Outline one cause of physical water scarcity.","Low rainfall or high evaporation in arid regions|low rainfall|arid|drought|evaporation|desert","So demand exceeds the available supply|demand exceeds|not enough|over abstraction|overuse",{model:"In arid regions low rainfall and high evaporation mean demand for water exceeds the available supply.",tip:"Compare with economic scarcity."}],
["A.3","Outline",2,"Outline salinization.","Irrigation water evaporates, leaving salts in the soil|evaporates|salts|salt|irrigation","Reducing soil fertility and crop yields|fertility|yields|infertile|crops die",{model:"When irrigation water evaporates it leaves salts behind in the soil, reducing fertility and crop yields.",tip:"A problem in hot, dry areas."}],
["A.3","Outline",2,"Outline one consequence of water scarcity for people.","Less water for drinking, sanitation and farming|drinking|sanitation|farming|crops|food","Leading to disease, food shortages or conflict over water|disease|food shortages|conflict|migration|time collecting",{model:"Water scarcity leaves less water for drinking and sanitation, increasing disease.",tip:"Consequence plus effect."}],
["A.3","Outline",2,"Outline two ways to improve water quality in a river.","Treat sewage and industrial waste before it is discharged|sewage treatment|treat|waste water|wastewater|regulate","Reduce fertilizer runoff, e.g. with buffer strips beside rivers|buffer strips|less fertiliser|less fertilizer|fertilizer runoff|riparian",{model:"Treating sewage before discharge and planting buffer strips to reduce fertilizer runoff both improve river water quality.",tip:"Point and diffuse sources."}],
["A.4","Outline",2,"Outline desalination, with one disadvantage.","Removing salt from seawater to produce fresh water|removing salt|seawater|fresh water|reverse osmosis","But it uses a lot of energy and produces brine waste|energy|expensive|brine|costly",{model:"Desalination removes salt from seawater to make fresh water, but it uses a lot of energy and produces brine.",tip:"Common in the Middle East."}],
["A.4","Outline",2,"Outline why transboundary rivers can cause conflict.","Upstream countries can reduce flow by building dams or taking water|upstream|dams|reduce flow|take water|abstraction","Harming countries downstream, e.g. on the Nile (GERD) or the Mekong|downstream|nile|gerd|mekong|egypt|ethiopia",{model:"Upstream countries can reduce the flow by building dams, harming downstream countries, as with Ethiopia's GERD and Egypt.",tip:"Name a river."}],
["A.4","Outline",2,"Outline one advantage of drip irrigation.","Water is delivered directly to plant roots|directly to roots|roots|targeted|precise","Reducing water loss by evaporation and runoff|less evaporation|saves water|reduces water loss|efficient",{model:"Drip irrigation delivers water straight to the roots, reducing losses to evaporation and runoff.",tip:"Advantage plus why."}],
["A.4","Outline",2,"Outline the role of wetlands in water management.","They store floodwater and release it slowly|store|absorb|floodwater|release slowly|sponge","And filter pollutants, improving water quality|filter|pollutants|water quality|clean",{model:"Wetlands store floodwater and release it slowly, and filter pollutants, improving water quality.",tip:"Natural infrastructure."}],
["B.1","Outline",2,"Outline La Niña.","Stronger than normal trade winds push warm water further west|stronger trade winds|trade winds|warm water west|colder east","Bringing heavier rain to Australia and Indonesia and drought to Peru|australia|indonesia|drought|peru|south america|heavy rain",{model:"In La Niña stronger trade winds push warm water further west, bringing heavy rain to Australia and Indonesia and drought to Peru.",tip:"The opposite of El Niño."}],
["B.1","Outline",2,"Outline how ocean currents affect climate.","Warm currents carry heat polewards, warming coasts, e.g. the Gulf Stream|warm currents|gulf stream|north atlantic drift|warmer","Cold currents cool coasts and can help create deserts|cold currents|cool|deserts|humboldt|benguela|dry",{model:"Warm currents such as the Gulf Stream warm coasts, while cold currents cool them and help create coastal deserts.",tip:"Give named currents."}],
["B.1","Outline",2,"Outline why sea temperatures are rising.","The oceans absorb most of the extra heat trapped by greenhouse gases|absorb|extra heat|greenhouse|90","Because water has a high heat capacity|heat capacity|specific heat|stores heat",{model:"The oceans absorb over 90% of the extra heat trapped by greenhouse gases, because water has a high heat capacity.",tip:"The ocean is a heat sink."}],
["B.1","Outline",2,"Outline how tropical cyclones form.","Over oceans warmer than about 26–27 °C|26|27|warm ocean|warm water","Rising moist air condenses, releasing latent heat that powers the storm; the Coriolis effect makes it spin|latent heat|condenses|coriolis|spin|low pressure|rising air",{model:"Over oceans warmer than about 27 °C, warm moist air rises and condenses, releasing latent heat that powers the storm, and the Coriolis effect makes it spin.",tip:"Conditions plus process."}],
["B.2","Outline",2,"Outline how a wave-cut platform forms.","Waves erode the base of a cliff, forming a notch|notch|base|undercut","The cliff above collapses and retreats, leaving a flat rocky area|collapses|retreats|flat|rocky",{model:"Waves erode a notch at the base of a cliff; the cliff above collapses and retreats, leaving a flat rocky platform.",tip:"Visible at low tide."}],
["B.2","Outline",2,"Outline how a tombolo forms.","Longshore drift deposits sediment|longshore drift|deposition|deposits|sediment","Forming a ridge that joins an island to the mainland|joins|island|mainland|connects",{model:"Longshore drift deposits sediment as a ridge that joins an island to the mainland.",tip:"E.g. Chesil Beach."}],
["B.2","Distinguish",2,"Distinguish between swash and backwash.","Swash: water moving up the beach after a wave breaks|up the beach|moves up|onshore","Backwash: water returning down the beach|down the beach|back down|returns|offshore",{model:"Swash is water moving up the beach after a wave breaks; backwash is water running back down.",tip:"Their strength decides the wave type."}],
["B.2","Outline",2,"Outline how coastal sand dunes develop.","Onshore winds blow dry sand inland, where obstacles trap it|onshore winds|wind blows|dry sand|trapped","Pioneer plants such as marram grass stabilize the sand, and dunes develop through succession|marram|pioneer|stabilize|stabilise|succession|vegetation",{model:"Onshore winds blow dry sand inland where obstacles trap it; marram grass stabilizes it and dunes develop through succession.",tip:"Embryo → fore → grey dunes."}],
["B.3","Outline",2,"Outline what groynes do.","Wooden or rock barriers built at right angles to the beach|barriers|right angles|wooden|rock|fences","Trapping sediment moved by longshore drift, building up the beach|trap|traps|longshore drift|build up|wider beach",{model:"Groynes are barriers at right angles to the beach that trap sediment moved by longshore drift, building up the beach.",tip:"Hard engineering."}],
["B.3","Outline",2,"Outline one disadvantage of groynes.","They starve beaches further along the coast of sediment|starve|downdrift|further along|terminal groyne|elsewhere","Increasing erosion there|increased erosion|erosion|erode|erodes|cliffs",{model:"Groynes trap sediment, starving beaches further down the coast, which then erode faster.",tip:"Solving one problem creates another."}],
["B.3","Outline",2,"Outline integrated coastal zone management (ICZM).","Managing the whole coastline as one connected system|whole coastline|whole coast|holistic|sediment cell","Involving all stakeholders and balancing conflicting uses sustainably|stakeholders|balancing|conflicting|uses|sustainable",{model:"ICZM manages a whole stretch of coast as one system, involving all stakeholders and balancing conflicting uses sustainably.",tip:"Often uses sediment cells."}],
["B.3","Outline",2,"Outline why coastal management can cause conflict between stakeholders.","Groups want different things, e.g. homeowners want defences but conservationists want natural processes|homeowners|conservationists|different groups|tourism|fishermen","And defences are expensive, so not every area can be protected|expensive|costly|funding|cost benefit|every area|limited budget",{model:"Homeowners want defences while conservationists prefer natural processes, and defences are too expensive to protect every area.",tip:"Who wins, who loses?"}],
["B.4","Outline",2,"Outline the causes of coral bleaching.","Higher sea temperatures stress the corals|higher temperatures|warmer water|warming|heat","So corals expel their algae (zooxanthellae) and turn white|expel|algae|zooxanthellae|white",{model:"Warmer water stresses corals, which expel their symbiotic algae and turn white.",tip:"Acidification adds to the stress."}],
["B.4","Outline",2,"Outline the Great Pacific Garbage Patch.","A concentration of plastic waste in the North Pacific|plastic|waste|rubbish|debris","Collected by circular currents (gyres)|gyre|gyres|currents|circular",{model:"It is a concentration of plastic debris in the North Pacific, gathered by a circular ocean current (gyre).",tip:"Mostly microplastics."}],
["B.4","Outline",2,"Outline one way to manage fish stocks sustainably.","E.g. quotas, marine protected areas or minimum net mesh sizes|quotas|marine protected areas|mpa|net size|mesh|no take|seasons","Allowing fish populations to recover and breed|recover|breed|reproduce|replenish",{model:"Fishing quotas limit catches so fish populations can recover and breed.",tip:"Method plus effect."}],
["B.4","Outline",2,"Outline the importance of mangroves.","They protect coasts from storm surges and erosion|protect|storm surge|erosion|buffer","And provide nursery habitats for fish and store carbon|nursery|habitat|fish|carbon|biodiversity",{model:"Mangroves protect coasts from storm surges and erosion, provide nursery habitats for fish and store carbon.",tip:"Physical and ecological value."}],
["C.1","Outline",2,"Outline why high-altitude areas are cold.","The air is thinner (lower pressure), so it holds less heat|thinner|lower pressure|less dense|expands","Temperature falls by about 6.5 °C per 1000 m (the lapse rate)|lapse rate|6.5|1000 m|falls with height",{model:"At altitude the air is thinner and holds less heat; temperature falls about 6.5 °C per 1000 m.",tip:"The environmental lapse rate."}],
["C.1","Outline",2,"Outline why hot deserts receive very little rain.","Dry air sinks in the subtropical high-pressure belt|sinking|high pressure|subtropical|descending","Rain shadows or cold ocean currents also reduce rainfall|rain shadow|cold currents|far from the sea|continental",{model:"Sinking dry air in the subtropical high-pressure belt prevents rain, and rain shadows or cold currents add to the dryness.",tip:"Hadley cell."}],
["C.1","Define",2,"Define a periglacial environment.","A cold region on the edge of glaciers or ice sheets|edge of glaciers|near ice sheets|cold|edge","With permafrost and freeze–thaw processes|permafrost|freeze thaw|frozen ground",{model:"A periglacial environment is a cold region at the edge of glaciers or ice sheets, with permafrost and freeze–thaw processes.",tip:"Peri = around."}],
["C.1","Outline",2,"Outline two challenges of living in a hot desert.","Extreme heat and lack of water|heat|lack of water|water shortage|dehydration","Poor soils for farming, or isolation and poor access|poor soils|farming|isolation|remote|access|sandstorms",{model:"Extreme heat and lack of water, and poor soils that make farming difficult.",tip:"Two different challenges."}],
["C.2","Outline",2,"Outline how a glacial trough (U-shaped valley) forms.","A glacier erodes the valley floor and sides by plucking and abrasion|plucking|abrasion|glacier|erodes","Widening and deepening the former river valley, leaving steep sides and a flat floor|widening|deepening|steep sides|flat floor|v shaped",{model:"A glacier erodes a river valley by plucking and abrasion, widening and deepening it into a U shape with steep sides and a flat floor.",tip:"V → U."}],
["C.2","Outline",2,"Outline how a drumlin forms.","Glacial till is deposited and moulded beneath a moving ice sheet|till|deposited|moulded|molded|beneath","Forming an egg-shaped hill with its steep end facing up-ice|egg shaped|elongated|steep end|stoss|streamlined",{model:"Till deposited beneath moving ice is moulded into an elongated, egg-shaped hill with its steep end facing up-ice.",tip:"Shows ice direction."}],
["C.2","Outline",2,"Outline how a mesa forms in a hot desert.","A cap of resistant rock protects softer rock beneath|resistant|cap|hard rock|caprock","Flash floods and wind erosion remove the surrounding rock, leaving a flat-topped hill|flat topped|flat top|surrounding rock|flash floods|wind erosion",{model:"A resistant caprock protects softer rock beneath while flash floods and wind remove the surrounding rock, leaving a flat-topped hill.",tip:"Smaller ones are buttes."}],
["C.2","Outline",2,"Outline exfoliation in hot deserts.","Rock heats and expands by day, then cools and contracts at night|expands|contracts|heats|cools|day and night","So the outer layers peel off|peel|layers|flake",{model:"Rock surfaces heat and expand by day and cool and contract at night, so the outer layers peel off.",tip:"Also called onion-skin weathering."}],
["C.3","Outline",2,"Outline one challenge of building on permafrost.","Heat from buildings can thaw the permafrost|thaw|melt|heat","Causing subsidence that damages buildings, roads and pipelines|subsidence|sinks|damage|cracks|collapse",{model:"Heat from buildings thaws the permafrost, causing subsidence that damages buildings and pipelines; they are often built on piles.",tip:"Solutions: piles, gravel pads."}],
["C.3","Outline",2,"Outline one renewable energy opportunity in hot deserts.","Solar power from very high sunshine levels|solar|sunshine|sun","E.g. Noor Ouarzazate in Morocco, supplying distant cities|noor|morocco|ouarzazate|export|cities|large scale",{model:"Hot deserts receive intense sunshine for solar power, as at Noor Ouarzazate in Morocco.",tip:"Name a project."}],
["C.3","Outline",2,"Outline one impact of oil extraction in a cold environment.","Oil spills or pipeline leaks damage fragile ecosystems|oil spills|spill|leaks|pollution|exxon valdez","Which recover slowly because of the cold and short growing season|recover slowly|slow|fragile|cold|short growing season",{model:"Oil spills damage fragile ecosystems that recover slowly because of the cold and short growing season.",tip:"E.g. Exxon Valdez, 1989."}],
["C.3","Outline",2,"Outline why extreme environments are fragile.","Ecosystems recover slowly from damage|recover slowly|slow recovery|slow growth|long time","Because of the harsh climate, short growing season and low biodiversity|harsh|short growing season|low biodiversity|cold|dry",{model:"Their ecosystems recover very slowly from damage because of the harsh climate, short growing season and low biodiversity.",tip:"Slow recovery is the key idea."}],
["C.4","Outline",2,"Outline the causes of desertification.","Overgrazing, deforestation and over-cultivation remove vegetation|overgrazing|deforestation|over cultivation|vegetation removed","Combined with drought, the soil is eroded and the land becomes desert|drought|climate change|erosion|soil|less rainfall",{model:"Overgrazing, deforestation and over-cultivation strip vegetation; combined with drought, soil erodes and land turns to desert.",tip:"Human and physical causes."}],
["C.4","Outline",2,"Outline the Great Green Wall initiative.","A belt of trees and vegetation planned across the Sahel|trees|vegetation|planting|belt","To stop desertification and restore degraded land|desertification|restore|degraded|land",{model:"The Great Green Wall is a planned belt of trees and vegetation across the Sahel to stop desertification and restore degraded land.",tip:"African Union project."}],
["C.4","Outline",2,"Outline one threat to the Antarctic environment.","Tourism, krill fishing, or warming that melts ice shelves|tourism|krill|fishing|ice shelves|warming|climate change","Damaging fragile ecosystems or raising sea levels|fragile ecosystems|penguins|sea level|sea levels|food chain|food web",{model:"Warming is melting Antarctic ice shelves, threatening ecosystems and raising sea levels.",tip:"Threat plus effect."}],
["C.4","Outline",2,"Outline one way glacier retreat affects mountain communities.","Glacial lake outburst floods (GLOFs)|glof|outburst|floods|lake","And less meltwater for drinking, irrigation and hydroelectricity|meltwater|irrigation|drinking|hydroelectric|water supply",{model:"Retreating glaciers create unstable lakes that can burst (GLOFs), and in the long term less meltwater is available for drinking and irrigation.",tip:"Short- and long-term."}],
["D.1","Outline",2,"Outline what happens at a conservative (transform) plate boundary.","Plates slide past each other|slide past|sideways|past each other|horizontal","Friction builds up stress, released as earthquakes; there are no volcanoes|earthquakes|friction|stress|stick|san andreas",{model:"At a conservative boundary plates slide past each other; friction builds up stress that is released as earthquakes, but there are no volcanoes.",tip:"E.g. the San Andreas Fault."}],
["D.1","Outline",2,"Outline how hotspot volcanoes form.","A plume of hot magma rises from the mantle|plume|mantle|magma rises","As the plate moves over it, a chain of volcanoes forms, e.g. Hawaii|chain|hawaii|plate moves|islands",{model:"A plume of magma rises from the mantle; as the plate moves over it, a chain of volcanoes forms, as in Hawaii.",tip:"Not at a plate boundary."}],
["D.1","Outline",2,"Outline slab pull.","Dense oceanic plate sinks into the mantle at a subduction zone|sinks|subduction|dense|oceanic","Dragging the rest of the plate with it|drags|dragging|rest of the plate|whole plate",{model:"At a subduction zone the dense oceanic plate sinks into the mantle, dragging the rest of the plate after it.",tip:"Thought to be the main driving force."}],
["D.1","Outline",2,"Outline how fold mountains form.","Where two continental plates collide|two continental plates|collision|continental","Rock is crumpled and forced upwards, e.g. the Himalayas|crumpled|folded|forced up|uplift|himalayas",{model:"Where two continental plates collide, rock is crumpled and forced upwards, forming fold mountains such as the Himalayas.",tip:"Neither plate subducts."}],
["D.2","Define",2,"Define the Volcanic Explosivity Index (VEI).","A scale measuring the size of volcanic eruptions|scale|measure|size of eruptions|magnitude","From 0 to 8, based on the volume of material ejected and plume height|0 to 8|volume|ejected|plume height|logarithmic",{model:"The VEI measures the size of eruptions on a 0–8 scale, based on the volume of material ejected and plume height.",tip:"Each step is ten times bigger."}],
["D.2","Outline",2,"Outline why liquefaction happens during earthquakes.","Shaking makes waterlogged soil lose its strength|waterlogged|saturated|loses strength|shaking","So it behaves like a liquid and buildings sink or topple|liquid|sink|topple|collapse",{model:"Shaking makes waterlogged soil lose its strength and behave like a liquid, so buildings sink or topple.",tip:"A secondary hazard."}],
["D.2","Define",2,"Define the moment magnitude scale.","A measure of the energy released by an earthquake|energy released|energy","It is logarithmic: each whole number is about 32 times more energy|logarithmic|32|times more",{model:"The moment magnitude scale measures the energy released by an earthquake; it is logarithmic, with each step about 32 times more energy.",tip:"Replaced the Richter scale."}],
["D.2","Outline",2,"Outline why volcanic eruptions are easier to predict than earthquakes.","Volcanoes give warning signs such as small earthquakes, ground swelling and gas emissions|warning signs|ground swelling|bulging|gas|tremors|tiltmeters","Which can be monitored, whereas earthquakes happen suddenly|monitored|sudden|no warning|seismometers",{model:"Volcanoes give warning signs such as small tremors, swelling and gas emissions that can be monitored; earthquakes strike without warning.",tip:"Prediction versus forecasting."}],
["D.3","Define",2,"Define vulnerability to hazards.","How likely people are to be harmed by a hazard|likely to be harmed|susceptible|exposed|risk of harm","Depending on social, economic and physical factors such as poverty|poverty|social|economic|education|housing",{model:"Vulnerability is how likely people are to be harmed by a hazard, depending on factors such as poverty and housing quality.",tip:"Risk = hazard × vulnerability ÷ capacity."}],
["D.3","Outline",2,"Outline why population density affects hazard risk.","More people live in the hazard zone|more people|exposed|densely populated","So more can be killed or affected|more deaths|more casualties|more affected",{model:"In densely populated areas more people are exposed to a hazard, so more can be killed or affected.",tip:"Exposure."}],
["D.3","Outline",2,"Outline the Pressure and Release (PAR) model.","Disaster risk results from a hazard meeting vulnerable people|hazard|vulnerability|vulnerable","Vulnerability builds from root causes through dynamic pressures to unsafe conditions|root causes|dynamic pressures|unsafe conditions|progression",{model:"The PAR model shows disasters happen when a hazard meets vulnerability, which builds from root causes through dynamic pressures to unsafe conditions.",tip:"Release the pressure by reducing vulnerability."}],
["D.3","Outline",2,"Outline one reason why deaths from hazards have fallen globally.","Better warning systems, building codes and preparedness|warning systems|early warning|building codes|preparedness|evacuation","Allowing more people to evacuate or survive|evacuate|survive|fewer deaths|safer",{model:"Early warning systems give people time to evacuate, so fewer die.",tip:"Even as economic losses rise."}],
["D.4","Outline",2,"Outline how early warning systems reduce deaths from hazards.","Monitoring detects hazards such as tsunamis or cyclones in advance|monitoring|detect|sensors|buoys|satellites","Giving people time to evacuate|evacuate|time|move to safety|shelters",{model:"Monitoring with sensors and satellites detects hazards early, giving people time to evacuate.",tip:"E.g. the Indian Ocean tsunami warning system."}],
["D.4","Outline",2,"Outline the role of insurance in hazard resilience.","It spreads the financial cost of a disaster|financial|cost|pay out|compensation","Helping people and businesses rebuild quickly|rebuild|recover|reconstruct",{model:"Insurance spreads the financial cost of disasters, helping people and businesses rebuild quickly.",tip:"Often unaffordable in poorer countries."}],
["D.4","Outline",2,"Outline one way buildings can be designed to resist earthquakes.","Cross-bracing, base isolators or flexible steel frames|cross bracing|base isolation|rubber|flexible|steel frame|shock absorbers|dampers","Which absorb or reduce shaking so the building doesn't collapse|absorb|reduce shaking|sway|don t collapse|stay standing",{model:"Base isolators absorb shaking, so the building moves less and doesn't collapse.",tip:"Design plus effect."}],
["D.4","Outline",2,"Outline the Sendai Framework (2015–2030).","A UN agreement to reduce disaster risk and losses|reduce disaster risk|disaster risk reduction|losses|united nations","Through prevention, preparedness and building back better|prevention|preparedness|build back better|resilience|targets",{model:"The Sendai Framework is a UN agreement to reduce disaster risk through prevention, preparedness and building back better.",tip:"Global targets to 2030."}],
]);

QB("geo", [
["E.1","Distinguish",2,"Distinguish between domestic and international tourism.","Domestic: travelling within one's own country|own country|within the country|same country","International: travelling to another country|another country|abroad|overseas|different country",{model:"Domestic tourism is travel within your own country; international tourism is travel to another country.",tip:"Simple, but be precise."}],
["E.1","Outline",2,"Outline how low-cost airlines have changed tourism.","Cheaper flights made foreign travel affordable to more people|cheaper flights|cheap flights|affordable|more people","Opening up new destinations and short city breaks|new destinations|city breaks|short breaks|weekend",{model:"Low-cost airlines made flying affordable to more people, opening up new destinations and short city breaks.",tip:"A cause of tourism growth."}],
["E.1","Outline",2,"Outline the role of social media in tourism.","Images shared online make places popular very quickly|images|instagram|shared|viral|influencers","Which can lead to overtourism at popular sites|overtourism|crowds|honeypot|overcrowding",{model:"Images shared on social media make places popular very quickly, sometimes causing overtourism.",tip:"Instagram tourism."}],
["E.1","Define",2,"Define a honeypot site.","A place that attracts very large numbers of tourists|large numbers of tourists|large numbers of visitors|many tourists|many visitors|very popular","Causing congestion and environmental pressure|congestion|crowding|overcrowding|footpath erosion|litter",{model:"A honeypot site attracts very large numbers of tourists, causing congestion and environmental pressure.",tip:"E.g. Venice."}],
["E.2","Outline",2,"Outline the multiplier effect of tourism.","Tourist spending creates jobs and income|spending|jobs|income","Which is spent again locally, creating further jobs|spent again|further|knock on|local economy|suppliers",{model:"Tourist spending creates jobs and income, which are spent again in the local economy, creating further jobs.",tip:"Leakage weakens it."}],
["E.2","Outline",2,"Outline one environmental impact of tourism on a local area.","Footpath erosion, litter or damage to habitats|footpath erosion|erosion|litter|habitats|wildlife|pollution","Caused by large numbers of visitors|visitors|crowds|trampling|large numbers",{model:"Large numbers of visitors trample paths, causing footpath erosion and damaging habitats.",tip:"Impact plus cause."}],
["E.2","Outline",2,"Outline why major sports venues are located where they are.","They need large areas of land and good transport links|land|transport|access|space","And a large population nearby to provide spectators|population|market|catchment|spectators",{model:"Major venues need large sites with good transport links and a large population nearby to supply spectators.",tip:"Think of a stadium you know."}],
["E.2","Outline",2,"Outline one way a national park manages visitors.","E.g. zoning, permits, park-and-ride or surfaced paths|zoning|permits|park and ride|surfaced paths|entry fees","Reducing environmental damage while still allowing access|reduce damage|reduces erosion|reduce erosion|still allowing|access|conservation",{model:"Surfacing popular paths reduces erosion while still letting visitors reach the sites.",tip:"Strategy plus effect."}],
["E.3","Outline",2,"Outline why the Olympic Games are an example of globalized sport.","Athletes and spectators from around the world take part|around the world|countries|athletes|global audience","They are broadcast worldwide and sponsored by TNCs|broadcast|television|tv|sponsors|tncs|media",{model:"Athletes from over 200 countries compete, and the Games are broadcast worldwide and sponsored by TNCs.",tip:"People, media and money."}],
["E.3","Outline",2,"Outline one positive and one negative impact of international tourism on a low-income country.","Positive: foreign exchange, jobs and new infrastructure|foreign exchange|jobs|infrastructure|income","Negative: leakage, seasonal or low-paid jobs, or cultural erosion|leakage|seasonal|low paid|cultural|exploitation|dependence",{model:"Tourism brings foreign exchange and jobs, but much income leaks abroad and many jobs are seasonal.",tip:"One of each."}],
["E.3","Outline",2,"Outline what is meant by sports migration.","Athletes moving to other countries to play|athletes|players|moving|move abroad","Attracted by higher pay or better facilities, e.g. footballers moving to Europe|higher pay|wages|facilities|footballers|europe",{model:"Sports migration is athletes moving abroad to play, attracted by higher pay and facilities, such as African footballers joining European clubs.",tip:"A global flow of people."}],
["E.3","Outline",2,"Outline the role of TNCs in international tourism.","Hotel chains, airlines and tour operators control much of the industry|hotel chains|airlines|tour operators|cruise","So profits often leave the host country|profits leave|leakage|abroad|foreign owned",{model:"Foreign-owned hotel chains, airlines and tour operators control much of the industry, so profits often leave the host country.",tip:"Link to leakage."}],
["E.4","Outline",2,"Outline one way sporting events can be made more sustainable.","E.g. reusing venues, public transport for fans, or renewable energy|reuse|existing venues|public transport|renewable|temporary","Reducing emissions and avoiding unused 'white elephant' stadiums|emissions|waste|carbon|white elephants",{model:"Using existing or temporary venues avoids building white elephants and reduces emissions and waste.",tip:"Paris 2024 reused venues."}],
["E.4","Outline",2,"Outline community-based tourism.","Tourism run by local communities|local communities|community run|locals|owned locally","Keeping profits local and respecting local culture|profits stay|benefits locals|culture|respect",{model:"Community-based tourism is run by local people, so profits stay in the community and local culture is respected.",tip:"Reduces leakage."}],
["E.4","Outline",2,"Outline two ways to reduce the environmental impact of cruise tourism.","Limit the number of ships or passengers|limit|caps|capping|cap the number|fewer ships|ban large ships|quotas","Use shore power and cleaner fuels to cut pollution|shore power|cleaner fuels|lng|pollution|emissions",{model:"Capping the number of ships and requiring shore power or cleaner fuels both reduce pollution.",tip:"E.g. Venice banned large ships."}],
["E.4","Outline",2,"Outline the role of tourist taxes in managing tourism.","A charge per visitor or per night|charge|fee|per night|levy","Raising money for conservation and discouraging excess visitors|raise money|conservation|fewer visitors|reduce numbers|deter",{model:"A tourist tax charges visitors per night, raising money for conservation and discouraging too many visitors.",tip:"E.g. Bhutan, Venice."}],
["F.1","Define",2,"Define stunting.","Low height for age in children|height for age|short|low height","Caused by long-term undernutrition|long term|chronic|undernutrition|malnutrition",{model:"Stunting is low height for age in children, caused by long-term undernutrition.",tip:"Compare with wasting."}],
["F.1","Outline",2,"Outline the epidemiological transition.","As countries develop, the main causes of death change|causes of death|main causes","From infectious diseases to non-communicable diseases such as heart disease|infectious|non communicable|ncd|heart disease|cancer|degenerative",{model:"As countries develop, the main causes of death shift from infectious diseases to non-communicable diseases such as heart disease and cancer.",tip:"Parallels the DTM."}],
["F.1","Define",2,"Define disability-adjusted life years (DALYs).","Years of healthy life lost through ill health or early death|years lost|ill health|early death|healthy life","A measure of the overall burden of disease|burden of disease|burden",{model:"DALYs are the years of healthy life lost through ill health, disability or early death, measuring the burden of disease.",tip:"One DALY = one lost year of healthy life."}],
["F.1","Outline",2,"Outline why obesity is rising globally.","Diets higher in processed food, sugar and fat|processed|sugar|fat|fast food|calories","And less physical activity as lifestyles become sedentary|sedentary|less exercise|physical activity|cars|screens",{model:"Diets contain more processed, sugary and fatty food, and lifestyles are more sedentary.",tip:"The nutrition transition."}],
["F.2","Outline",2,"Outline expansion diffusion of a disease.","The disease spreads outwards from its source|spreads outwards|from a source|outwards","While remaining in the original area|remains|original area|still present",{model:"In expansion diffusion a disease spreads outwards from its source while remaining in the original area.",tip:"Compare with relocation."}],
["F.2","Outline",2,"Outline hierarchical diffusion of a disease.","The disease spreads through an ordered sequence of places|ordered|sequence|order|ranked","E.g. from large cities to smaller towns|large cities|smaller towns|big cities|towns|villages",{model:"In hierarchical diffusion a disease spreads through an ordered sequence of places, such as from large cities to smaller towns.",tip:"Follows the urban hierarchy."}],
["F.2","Outline",2,"Outline one negative impact of the Green Revolution.","Heavy use of fertilizers and pesticides polluted water|fertilisers|fertilizers|pesticides|pollution|chemicals","Poorer farmers couldn't afford the inputs, increasing inequality, and groundwater was overused|inequality|couldn t afford|debt|groundwater|water tables",{model:"Heavy use of fertilizers and pesticides polluted water, and poorer farmers who couldn't afford the inputs fell into debt.",tip:"Environmental and social."}],
["F.2","Outline",2,"Outline how climate affects the spread of malaria.","Mosquitoes need warm temperatures and standing water|warm|temperatures|standing water|stagnant","So warming may spread malaria to higher altitudes and latitudes|higher altitudes|new areas|spread|latitudes",{model:"Malaria mosquitoes need warmth and standing water, so warming may spread malaria to higher altitudes and latitudes.",tip:"Vector-borne disease."}],
["F.3","Outline",2,"Outline the role of the Food and Agriculture Organization (FAO).","A UN agency working to defeat hunger|hunger|food security|un agency|united nations","By giving advice, data and support to improve farming|advice|data|support|farming",{model:"The FAO is a UN agency that works to defeat hunger by giving advice, data and support to improve farming.",tip:"A global stakeholder."}],
["F.3","Outline",2,"Outline one way governments can improve health.","E.g. vaccination programmes, clean water or health education|vaccination|vaccines|clean water|sanitation|health education|free healthcare","Reducing disease and raising life expectancy|reduce disease|reduces disease|life expectancy|fewer deaths|infant mortality",{model:"Vaccination programmes reduce infectious disease and raise life expectancy.",tip:"Policy plus effect."}],
["F.3","Outline",2,"Outline the role of agribusiness in food systems.","Large companies control production, processing and distribution|large companies|corporations|tncs|control|processing","Increasing efficiency but reducing small farmers' power and biodiversity|efficiency|small farmers|monoculture|biodiversity|power",{model:"Agribusiness corporations control production and processing, raising efficiency but reducing small farmers' power and biodiversity.",tip:"Positive and negative."}],
["F.3","Outline",2,"Outline one way pharmaceutical companies affect global health.","They develop medicines and vaccines|medicines|vaccines|drugs|research","But high prices or patents can limit access in poorer countries|prices|patents|access|expensive|poorer countries",{model:"Pharmaceutical companies develop vital medicines and vaccines, but high prices and patents can limit access in poorer countries.",tip:"E.g. HIV drugs."}],
["F.4","Outline",2,"Outline the role of genetically modified (GM) crops in food security.","They can raise yields or resist pests and drought|yields|pests|drought|resistant","But there are concerns about safety, biodiversity and corporate control of seeds|concerns|biodiversity|safety|corporate|seeds|patents",{model:"GM crops can raise yields and resist pests and drought, but there are concerns about biodiversity and corporate control of seeds.",tip:"Benefit plus concern."}],
["F.4","Outline",2,"Outline one threat posed by emerging diseases.","New diseases such as COVID-19 can spread quickly through global travel|covid|global travel|spread quickly|pandemic","Overwhelming health systems and economies|overwhelm|health systems|economy|deaths|lockdowns",{model:"New diseases such as COVID-19 spread quickly through global travel, overwhelming health systems and economies.",tip:"Most come from animals."}],
["F.4","Outline",2,"Outline how insects could contribute to future food supplies.","They are high in protein|protein|nutritious","And need far less land, water and feed than livestock, with lower emissions|less land|less water|less feed|lower emissions|efficient",{model:"Insects are rich in protein and need far less land, water and feed than livestock, with lower emissions.",tip:"Cultural acceptance is the barrier."}],
["F.4","Outline",2,"Outline how climate change threatens future food security.","Higher temperatures, droughts and floods reduce crop yields|droughts|floods|yields|heat|crop failure","Especially in tropical and low-income regions|tropical|low income|poorer|africa|south asia",{model:"Heat, droughts and floods will reduce crop yields, especially in tropical, low-income regions.",tip:"Who is most at risk?"}],
["G.1","Define",2,"Define suburbanization.","The movement of people and businesses from the inner city to its edges|edge of the city|outskirts|out of the centre|outward","Leading to the growth of residential areas on the edge|growth of suburbs|suburbs grow|residential areas",{model:"Suburbanization is the outward movement of people and businesses from the inner city, leading to the growth of suburbs.",tip:"Linked to car ownership."}],
["G.1","Outline",2,"Outline why land values are highest in the CBD.","It is the most accessible part of the city|accessible|accessibility|transport links|central","So demand for land is high and space is limited|demand|competition|limited space|bid rent",{model:"The CBD is the most accessible part of the city, so demand for limited land is highest (bid-rent theory).",tip:"Bid-rent theory."}],
["G.1","Outline",2,"Outline the characteristics of the rural–urban fringe.","The zone at the edge of a city where urban and rural land uses mix|edge|mix|transition","E.g. retail parks, golf courses and farmland under development pressure|retail parks|golf|farmland|development pressure|greenbelt|green belt",{model:"The rural–urban fringe is the zone at a city's edge where retail parks and golf courses mix with farmland under development pressure.",tip:"A zone of conflict."}],
["G.1","Define",2,"Define urban segregation.","The separation of different groups into different areas of a city|separation|separate|different areas","By income, ethnicity or religion|income|ethnicity|ethnic|religion|wealth",{model:"Urban segregation is the separation of groups into different areas by income, ethnicity or religion.",tip:"E.g. gated communities."}],
["G.2","Outline",2,"Outline why many cities in high-income countries deindustrialized.","Factories closed or moved abroad to cheaper locations|moved abroad|cheaper|closed|global shift","Causing unemployment and derelict land in inner cities|unemployment|derelict|decline|inner city",{model:"Factories closed or moved to cheaper countries, leaving unemployment and derelict land in inner cities.",tip:"The global shift."}],
["G.2","Outline",2,"Outline the causes of rapid growth in megacities such as Lagos.","Rural–urban migration for jobs and services|migration|rural urban|jobs|services","And high natural increase among young migrants|natural increase|high birth rate|young",{model:"Lagos grows through rural–urban migration for jobs and services, and high natural increase among its young population.",tip:"Two causes."}],
["G.2","Define",2,"Define a primate city.","A city much larger than any other in the country|much larger|largest|more than twice","That dominates the country's economy and politics, e.g. Bangkok or Lima|dominates|economy|bangkok|lima|london|paris",{model:"A primate city is much larger than any other in its country and dominates its economy and politics, e.g. Bangkok.",tip:"Often over twice the next city."}],
["G.2","Outline",2,"Outline urban regeneration.","Improving run-down urban areas|improving|redevelop|run down|derelict|renewal","Through new housing, businesses and public spaces, e.g. London Docklands|housing|businesses|docklands|investment|public spaces",{model:"Urban regeneration improves run-down areas with new housing, businesses and public spaces, as in London Docklands.",tip:"Who benefits?"}],
["G.3","Outline",2,"Outline one cause of social deprivation in cities.","Unemployment and low incomes|unemployment|low incomes|poverty","Leading to poor housing, health and education|poor housing|health|education|crime",{model:"Unemployment and low incomes lead to poor housing, health and education in deprived areas.",tip:"A cycle of deprivation."}],
["G.3","Outline",2,"Outline why waste disposal is a challenge in fast-growing cities.","Waste is produced faster than services can collect it|faster than|can t collect|cannot collect|not collected|collection services|lack of collection","Leading to open dumping, burning and disease|open dumping|dumping|burning|landfill|disease",{model:"Waste grows faster than collection services, leading to open dumping, burning and disease.",tip:"E.g. Dharavi recycling."}],
["G.3","Outline",2,"Outline one cause of urban water pollution.","Untreated sewage or industrial waste discharged into rivers|sewage|industrial waste|untreated|factories","Especially where infrastructure hasn't kept up with growth|infrastructure|informal settlements|lack of treatment|growth",{model:"Untreated sewage and industrial waste flow into rivers where treatment infrastructure hasn't kept up with growth.",tip:"Cause plus context."}],
["G.3","Outline",2,"Outline how crime can be reduced in cities.","E.g. CCTV, street lighting, policing or community programmes|cctv|lighting|police|policing|community","And reducing deprivation through jobs and education|jobs|education|deprivation|youth",{model:"CCTV and better street lighting deter crime, while jobs and education reduce the deprivation behind it.",tip:"Short- and long-term."}],
["G.4","Outline",2,"Outline what a green belt is.","A zone of protected countryside around a city|protected|countryside|around a city|ring","Where building is restricted to stop urban sprawl|restricted|stop sprawl|urban sprawl|prevent",{model:"A green belt is protected countryside around a city where building is restricted to stop urban sprawl.",tip:"Pushes development to brownfield sites."}],
["G.4","Outline",2,"Outline how green roofs make cities more sustainable.","Plants on roofs absorb rainwater and insulate buildings|absorb rainwater|insulate|insulation|plants","Reducing flooding, the heat island effect and energy use|flooding|heat island|cooling|energy|biodiversity",{model:"Green roofs absorb rainwater and insulate buildings, reducing flooding, the urban heat island and energy use.",tip:"Several benefits."}],
["G.4","Outline",2,"Outline one advantage of building on brownfield sites.","Reuses derelict land and protects the countryside|reuse|derelict|protects countryside|greenfield|green belt","Close to existing services and infrastructure|services|infrastructure|transport|regenerat",{model:"Building on brownfield sites reuses derelict land, protecting the countryside, and is close to existing services.",tip:"Can be costly to clean up."}],
["G.4","Outline",2,"Outline the idea of an eco-city.","A city designed to minimize its environmental impact|minimize|minimise|low carbon|environmental impact|sustainable","Using renewable energy, efficient transport and recycling, e.g. Masdar or Curitiba|renewable|public transport|recycling|masdar|curitiba|freiburg",{model:"An eco-city is designed to minimize environmental impact, using renewable energy, public transport and recycling, like Curitiba.",tip:"Name an example."}],
]);
